	'setting_access_register_verify' => 'New User Registration Verification',
	'setting_access_register_verify_comment' => 'Select "None" for users to register directly; Select "Email Verification" to send a verification email to the registered Email to confirm the validity of the email (<strong>Enable "Send registration link via email" for automatic verification</strong>); Select "Manual Review" for administrators to manually determine whether to allow new user registration',
