	'setting_access_register_verify_ipwhite' => 'IP List Exempt from New User Registration Verification',
	'setting_access_register_verify_ipwhite_comment' => 'When users are from IP addresses in this list, registration succeeds directly without new user verification. One IP per line, you can enter full address or just IP prefix, e.g. "192.168." (without quotes) matches all addresses in 192.168.0.0～192.168.255.255 range, leave blank for no setting',
	'setting_access_register_maildomain' => 'Registration Email Domain Restriction',
	'setting_access_register_maildomain_comment' => 'Select "None" to directly disable this feature; select "Whitelist Mode", only email domains in the restriction list can register; select "Blacklist Mode", email domains in the restriction list cannot register.',
