	'setting_access_access_ipaccess' => 'IP List Allowed to Access Site',
	'setting_access_access_ipaccess_comment' => 'Only users from IP addresses in this list can access this site. Access from addresses outside the list will be considered as IP banned. This is only applicable to very specific occasions such as internal sites of enterprises or schools. This function has no exceptions for administrators. If the administrator is not within this list, they will also be unable to log in. Please use this function with caution. One IP per line, you can enter full address or just IP prefix, e.g. "192.168." (without quotes) matches all addresses in 192.168.0.0～192.168.255.255 range, leave blank for all IPs to be accessible except those explicitly banned',
	'setting_access_access_adminipaccess' => 'IP List Allowed to Access Admin CP',
	'setting_access_access_adminipaccess_comment' => 'Only users from IP addresses in this list can access the site Admin CP. Access from addresses outside the list will be denied, but they can still access the frontend user interface. Please use this function with caution. One IP per line, you can enter full address or just IP prefix, e.g. "192.168." (without quotes) matches all addresses in 192.168.0.0～192.168.255.255 range, leave blank for all IPs to be able to access the Admin CP except those explicitly banned',
	'setting_access_access_domainwhitelist' => 'List of Domains Allowed to Post',
	'setting_access_access_domainwhitelist_comment' => 'When a user group is prohibited from posting URLs, or URLs are not parsed, URLs under domains in this list can still be posted and parsed normally. One domain per line, default is that the site domain can be posted normally',
	'setting_access_access_domainwhitelist_affectimg' => 'Do Not Parse Remote Images Outside This List',

