	'setting_domain' => 'Domain Settings',
	'setting_domain_base' => 'Basic Settings',
	'setting_domain_base_tips' => "<li>After setting a reserved subdomain, no one can apply for or use that domain</li><li>After enabling subdomains for personal space and groups, you need to set the root domains for <strong>{$_G['setting']['navs'][3]['navname']}</strong> and <strong>{$_G['setting']['navs'][4]['navname']}</strong> in <strong>Root Domain Settings</strong></li>",
	'setting_domain_app' => 'App Domain',
	'setting_domain_app_domain' => 'Domain',
	'setting_domain_app_tips' => '<li>Each bound domain cannot be the same. Domains do not need to add "<strong>http://</strong>" and should not end with "<strong>/</strong>", e.g.: portal.discuz.vip</li><li>When enabling any domain, you need to configure the default domain, otherwise it will cause multi-entry issues</li><li>When enabling multiple domains, please modify the cookiedomain value in config/config_global.php to set the cookie scope</li>',
	'setting_domain_app_mobile_tips' => 'When mobile domain is configured, non-mobile browser access will automatically redirect to the default domain',
	'setting_domain_root' => 'Root Domain Settings',
	'setting_domain_root_tips' => "<li>You can set a root subdomain for <strong>personal space, {$_G['setting']['navs'][3]['navname']}, forums, topics, and channels</strong>. For example: if a user applies for XXX.discuz.vip, the root domain should be: discuz.vip</li><li>After setting the subdomain root for <strong>personal space and {$_G['setting']['navs'][3]['navname']}</strong>, you also need to enable the corresponding subdomain switch in <strong>Basic Settings</strong> before users can apply for and bind subdomains in the relevant places, subject to the subdomain length limit of the user group</li><li>If the channel subdomain is bound to a directory, you need to configure the related binding operations in your environment yourself</li><li>It is not recommended to change different root domains to the same root domain midway</li>",
	'setting_domain_allow_space' => 'Enable Personal Space Subdomain',
	'setting_domain_allow_space_comment' => 'After enabling, you need to set the root domain and user group domain length before enabling domain application',
	'setting_domain_allow_group' => 'Enable Group Subdomain',
	'setting_domain_allow_group_comment' => 'After enabling, you need to set the root domain and user group domain length before enabling domain application',
	'setting_domain_hold_domain' => 'Reserved Subdomain',
	'setting_domain_hold_domain_comment' => 'Separate multiple with |, wildcards * can be used ',
