	'setting_profile_time_zone' => 'Timezone',
	'setting_profile_tips' => '<li>At least one user field group must be enabled. If none are enabled, all are enabled by default</li>',

	'setting_threadprofile_tpl_tpls' => '<li>{<b>tag</b>} Call to post user info tag without parameters.</li><li>{<b>tag</b>=<b>param</b>} Call to post user info tag with parameters, multiple parameters separated by ","</li><li>{<b>tag</b>}<b>HTML</b>{<b>*</b>}<b>HTML</b>{/<b>tag</b>} Display HTML content before and after {*} when the called content has a value</li><li>Tags in the format "<b>plugin:plugin_id</b>" are post user info tag calls added by plugins. Plugin developers must carefully read the content in <a href="https://open.dismall.com/?!devdoc" target="_blank">Discuz! Technical Documentation</a> before designing new post user info tags.</li>',

