	'setting_seo_opendetail' => 'Expand Detailed Settings',
	'setting_seo_closedetail' => 'Collapse Detailed Settings',
	'setting_seo_portal' => 'Portal Homepage',
	'setting_seo_global_tips' => '<li>Inserted variables must include curly braces "{}". When the application scope does not support this variable, the variable will not be displayed on the frontend (the separator after the variable will also not be displayed). Leave blank for system default settings, SEO customization supports manual writing.<br>The following are available SEO variables:&nbsp;<br></li>',
	'setting_seo_portal_tips' => '<li>Site Name&nbsp;<font class="highlight">{bbname}</font> (application scope: all positions)</li><li>Current Channel Name&nbsp;<font class="highlight">{curcat}</font> (application scope: except home page)</li><li>First-level Channel Name&nbsp;<font class="highlight">{firstcat}</font> (application scope: except home page)</li><li>Second-level Channel Name&nbsp;<font class="highlight">{secondcat}</font> (application scope: except home page)</li><li>Article Title&nbsp;<font class="highlight">{subject}</font> (application scope: article content page)</li><li>Article Summary&nbsp;<font class="highlight">{summary}</font> (application scope: article content page)</li><li>Article Author&nbsp;<font class="highlight">{user}</font> (application scope: article content page)</li><li>Page Number&nbsp;<font class="highlight">{page}</font> (application scope: article list page, article content page)</li>',
	'setting_seo_articlelist' => 'Article List',
	'setting_seo_article' => 'Article Content',
	'setting_seo_forum' => 'Forum Home',
	'setting_seo_forum_tips' => '<li>Site Name&nbsp;<font class="highlight">{bbname}</font> (application scope: all positions)</li><li>Current Forum Name&nbsp;<font class="highlight">{forum}</font> (application scope: except home page)</li><li>First-level Forum Name&nbsp;<font class="highlight">{fup}</font> (application scope: sub-forum thread list page and post content page)</li><li>Category Name&nbsp;<font class="highlight">{fgroup}</font> (application scope: except home page)</li><li>Post Title&nbsp;<font class="highlight">{subject}</font> (application scope: post content page)</li><li>Thread Summary&nbsp;<font class="highlight">{summary}</font> (application scope: post content page)</li><li>Thread Tags&nbsp;<font class="highlight">{tags}</font> (application scope: post content page)</li><li>Page Number&nbsp;<font class="highlight">{page}</font> (application scope: thread list page, post content page)</li>',
	'setting_seo_threadlist' => 'Thread List',
	'setting_seo_viewthread' => 'Post Content',
	'setting_seo_home' => 'Home Page',
	'setting_seo_home_tips' => '<li>Site Name&nbsp;<font class="highlight">{bbname}</font> (application scope: all positions)</li><li>Blog Title&nbsp;<font class="highlight">{subject}</font> (application scope: blog content page)</li><li>Blog/Album Author&nbsp;<font class="highlight">{user}</font> (application scope: blog and album content pages)</li><li>Blog Summary&nbsp;<font class="highlight">{summary}</font> (application scope: blog content page)</li><li>Blog Tags&nbsp;<font class="highlight">{tags}</font> (application scope: blog content page)</li><li>Album Name&nbsp;<font class="highlight">{album}</font> (application scope: album content page)</li><li>Album Description&nbsp;<font class="highlight">{depict}</font> (application scope: album content page)</li>',
