	'setting_seo_rewritestatus_plugin' => 'Plugin',
	'setting_seo_rewritestatus_comment' => 'URL staticization can improve search engine crawling. Enabling this feature requires adding corresponding Rewrite support to the Web server, and will slightly increase server load. You can also adjust the static format of each page, but you must not delete the tags. Leave blank to reset static format. Note: After modifying the static format, you need to modify the server\'s Rewrite rule settings',
