	'setting_cachethread' => 'Forum Page Cache Settings',
	'setting_cachethread_comment' => 'When enabled, page content is cached to static files, and visitor access speed will be greatly improved. Recommended for dedicated servers. For virtual hosting, please adjust cache validity according to actual situation',
	'setting_cachethread_indexlife' => 'Cache Forum Home Page Validity',
	'setting_cachethread_indexlife_comment' => 'Set the cache update time for the forum home page, in seconds. 0 means disabled (after disabling here, the cache coefficient will no longer take effect). Recommended setting is 900. This feature is only for guests',
	'setting_cachethread_life' => 'Cache Post Validity',
	'setting_cachethread_life_comment' => 'Set the cache update time for post pages, in seconds. 0 means disabled. Please adjust according to actual situation, recommended setting is 900. Additionally, please specify the post page cache coefficient by editing the forum',
	'setting_cachethread_dir' => 'Cache Directory',
	'setting_cachethread_dir_comment' => 'Default is data/threadcache directory. If you need to specify another directory, please make sure the directory you specify has write permission',
	'setting_cachethread_coefficient_set' => 'Cache Coefficient Batch Setting',
	'setting_cachethread_coefficient' => 'Cache Coefficient',
	'setting_cachethread_coefficient_comment' => 'Page cache function can temporarily cache threads frequently visited by members, alleviating server pressure on large forums. Cache threshold range is 0-100, recommended setting is 40, 0 means disabled. When disk space allows, appropriately increasing the cache coefficient can improve cache effect',
	'setting_cachethread_coefficient_forum' => 'Please select forums to set',
	'setting_cachethread_coefficient_forum_comment' => 'Will overwrite previous cache coefficient values, you can hold CTRL to select multiple',

	'setting_avatar' => 'Avatar Settings',

	'setting_memory' => 'Memory Optimization',
	'setting_memory_tips' => '<li>Enabling memory optimization will greatly improve program performance and server load capacity. Memory optimization requires server system and PHP extension module support</li><li>Currently supported memory optimization interfaces include Memcache, eAccelerator, Alternative PHP Cache (APC), Xcache, Redis, YAC, APCu. The optimization system will select interfaces in sequence based on the current server environment</li><li>Main settings for memory interfaces are located in config_global.php. You can perform advanced settings by editing config_global.php</li>',
