	'setting_memory_func_forumindex_comment' => '<span class="vtop tips2">Recommended to enable, time set to 30 seconds, in units of user group ID or \'for_robot\', data does not update during cache time</span>',
	'setting_memory_func_diyblock' => 'DIY Module Data',
	'setting_memory_func_diyblock_comment' => '<span class="vtop tips2">Recommended to enable, time set to 300 seconds, 5 minutes, in units of module ID, data does not update during cache time</span>',
	'setting_memory_func_diyblockoutput' => 'DIY Module Output',
	'setting_memory_func_diyblockoutput_comment' => '<span class="vtop tips2">Recommended to enable, time set to 30 seconds, in units of module ID, data does not update during cache time</span>',
	'setting_memory_func_common_member' => 'User Data',
	'setting_memory_func_common_member_comment' => '<span class="vtop tips2">Recommended to enable, time set to 0, never expires, in units of UID, cached data updates synchronously when table data is updated</span>',
	'setting_memory_func_forum_forum' => 'Forum Data',
	'setting_memory_func_forum_forum_comment' => '<span class="vtop tips2">Recommended to enable, time set to 0, never expires, in units of FID, cached data updates synchronously when table data is updated</span>',
	'setting_memory_func_forum_thread' => 'Thread Data',
	'setting_memory_func_forum_thread_comment' => '<span class="vtop tips2">Recommended to enable, time set to 172800 seconds, two days, in units of TID, cached data updates synchronously when table data is updated</span>',
	'setting_memory_func_forum_thread_forumdisplay' => 'Forum List Data',
