	'setting_serveropti' => 'Server Optimization',
	'setting_serveropti_maxonlines' => 'Maximum Online Users',
	'setting_serveropti_maxonlines_comment' => 'Please set a reasonable value, range 10~65535, recommended to set to about 10 times the average online number',
	'setting_serveropti_onlinehold' => 'Online Hold Time (minutes)',
	'setting_serveropti_onlinehold_comment' => 'Please set a reasonable value according to access situation. Sites with high traffic should lower this value. Setting range is 5-60. Settings that are too large or too small may increase server resource consumption',
	'setting_serveropti_jspath' => 'JS File URL',
	'setting_serveropti_jspath_comment' => 'Set the URL for site JS files. When set to a cache directory, the system will compress *.js files in the system directory and save them to the cache directory to improve read speed and user access speed',
	'setting_serveropti_jspath_default' => 'System Directory static/js/',
