	'setting_serveropti_jspath_custom' => 'Custom URL',
	'setting_serveropti_csspath' => 'CSS File URL',
	'setting_serveropti_csspath_comment' => 'Set the URL for site CSS file cache. After changing this setting, you need to update the template cache',
	'setting_serveropti_csspath_cache' => 'Cache Directory',
	'setting_serveropti_csspath_custom' => 'Custom URL',
	'setting_serveropti_searchctrl' => 'Search Time Limit (seconds)',
	'setting_serveropti_searchctrl_comment' => 'Intervals between two searches less than this time will be prohibited, 0 means no limit',
	'setting_serveropti_maxspm' => '<span class="spectitle">Maximum Search Count in 60 Seconds</u></i>',
	'setting_serveropti_maxspm_comment' => 'Maximum number of searches the site system responds to every 60 seconds, 0 means no limit. Note: If the server load is heavy, it is recommended to set to 5, or within the range of 5~20, to avoid data table locks caused by too frequent searches',
	'setting_serveropti_maxsearchresults' => 'Maximum Search Results',
	'setting_serveropti_maxsearchresults_comment' => 'Maximum number of results obtained per search, recommended default is 500, or within 1500',
	'setting_serveropti_gzipcompress' => 'Page Gzip Compression',
	'setting_serveropti_gzipcompress_comment' => 'Compress page content with gzip before transmission, which can speed up transmission. Requires PHP 4.0.4 or above and Zlib module support to use',
	'setting_serveropti_gzipcompress_disabled' => 'Your hosting does not support Zlib module, cannot enable this feature',
	'setting_serveropti_optimize_thread_view' => 'Optimize Thread View Count Update',
	'setting_serveropti_preventrefresh' => '<span class="spectitle">Enable Anti-refresh for View Count</span>',
	'setting_serveropti_preventrefresh_comment' => 'Select "No", each visit to thread, space, blog increases view count by 1, which will increase server pressure. It is recommended to select "Yes"',
	'setting_serveropti_delayviewcount' => '<span class="spectitle">Delayed Update for Attachment Download Count</span>',
	'setting_serveropti_delayviewcount_attach' => 'Attachment Download Count',
	'setting_serveropti_delayviewcount_thread_attach' => 'Thread View Count and Attachment Download Count',
	'setting_serveropti_delayviewcount_comment' => 'Delayed update of attachment view count can significantly reduce server load for high-traffic sites. Recommended to enable this feature',
	'setting_serveropti_nocacheheaders' => '<span class="spectitle">Disable Browser Caching</span>',
	'setting_serveropti_nocacheheaders_comment' => 'Disable browser caching of site pages, can be used to solve the problem of abnormal content refresh in very few browsers. Note: This feature will increase server load',
	'setting_serveropti_lazyload' => 'Enable Lazy Loading for Images',
	'setting_serveropti_lazyload_comment' => 'When enabled, images on the page are loaded only when they are in the browser\'s current window. This can significantly reduce server load for high-traffic sites. Recommended to enable this feature',
	'setting_serveropti_blockmaxaggregationitem' => '<span class="spectitle">Number of Items for Module Aggregation</span>',
	'setting_serveropti_blockmaxaggregationitem_comment' => 'This value affects the number of data items MySQL retrieves during module aggregation. Setting it too large will seriously affect MySQL performance. Setting it too small will affect the ideal degree of module aggregation result data. 0 disables this feature',
	'setting_serveropti_blockcachetimerange' => 'Module Update Time Interval',
	'setting_serveropti_blockcachetimerange_comment' => 'Set all modules to update within the specified time interval. You can avoid peak traffic periods based on website access situation. E.g.: 3am-7am',
	'setting_serveropti_blockcachetimerangepoint' => 'o\'clock',
	'setting_serveropti_sessionclose' => 'Disable Session Mechanism',
	'setting_serveropti_sessionclose_comment' => 'After disabling the session mechanism, server load can be significantly reduced. It is recommended to enable this feature when online users exceed 20,000 (Note: guest count and user online duration will no longer be counted, and the online user list function on forum home and section list pages will not be available)',
	'setting_serveropti_onlineguestsmultiple' => 'Online Count Estimation Ratio',
	'setting_serveropti_onlineguestsmultiple_comment' => 'After disabling session mechanism, total online people (including guests and users) ≈ actual online users * online count estimation ratio. Recommended value is around 10, can be a floating point number (Note: actual online user count cache period is 600 seconds)',

