	'setting_functions_archiverredirect' => 'Prohibit Users from Accessing Archiver',
	'setting_functions_archiverredirect_comment' => 'Select "Yes", when users access the Archiver page through search engine links, they will be automatically redirected to the original content page',
	'setting_functions_mod_status_comment' => 'Forum management work statistics allow moderators and administrators to understand the work status of forum moderators and other management personnel. Note: This feature will slightly increase system load',
