	'setting_functions_mod_losslessdel' => 'Time Limit for No Credit Deduction for Post Deletion (days)',
	'setting_functions_mod_losslessdel_comment' => 'Set the number of days ago when posts deleted by moderators or administrators from the frontend do not update user extended credits. Can be used to clean up old posts without losing the author\'s extended credits. 0 means disable this feature, always update user credits',
	'setting_functions_mod_warninglimit' => 'Auto Mute After How Many Warnings',
