	'setting_functions_mod_reasons' => 'Management Operation Reason Options',
	'setting_functions_user_reasons' => 'User Rating Reason Options',
	'setting_functions_mod_user_public' => 'Public Management Operator',
	'setting_functions_mod_user_public_comment' => 'When enabled, thread management operators will be displayed as the user\'s username and UID. Otherwise, thread management operators will only be displayed as "Management Team" without specific information. This also applies to system reminders and operation logs',
	'setting_functions_mod_reasons_public' => 'Public Management Operation Reason',
	'setting_functions_mod_reasons_comment' => 'This setting will be displayed when users perform some management operations. One reason per line. If there is a blank line, a separator line "--------" will be displayed. Users can select preset reason options in this setting or enter their own',
	'setting_functions_mod_reasons_public_comment' => 'When enabled, clicking thread operation records below the thread post will also show management operation reasons',
	'setting_functions_user_reasons_comment' => 'This setting will be displayed when users rate. One reason per line. If there is a blank line, a separator line "--------" will be displayed. Users can select preset reason options in this setting or enter their own',
	'setting_functions_mod_bannedmessages' => 'Hide Sensitive Post Content',
	'setting_functions_mod_bannedmessages_comment' => 'Select corresponding items to hide related information of deleted or banned users, showing "blocked" text in related positions',
	'setting_functions_mod_bannedmessages_thread' => 'Post Content',
	'setting_functions_mod_bannedmessages_avatar' => 'User Avatar',
	'setting_functions_mod_bannedmessages_signature' => 'User Signature',
	'setting_functions_mod_rewardexpiration' => 'Reward Thread Validity Period',
	'setting_functions_mod_rewardexpiration_comment' => 'Set the valid days for reward threads. When a reward thread exceeds the validity period and the reward has not been issued, moderators or administrators have the right to issue the reward on behalf of the thread author. 0 or blank means moderators or administrators are not allowed to perform this operation',
	'setting_functions_mod_moddetail' => '<span class="spectitle">Moderator Panel Shows Moderation Count</span>',
	'setting_functions_mod_moddetail_comment' => 'Set whether the moderator panel shows the specific number of threads, posts and users pending moderation',
	'setting_functions_heatthread_tips' => '<li>Thread heat is calculated by participation count, including replies, comments, favorites, shares, ratings, recommendations</li>',
	'setting_functions_heatthread' => 'Thread Heat',
	'setting_functions_heatthread_type' => 'Heat Calculation Method',
	'setting_functions_heatthread_type_comment' => 'After switching the heat calculation method, previously obtained heat values for threads will not be recalculated. Subsequent heat values will increase according to the new calculation method',
	'setting_functions_heatthread_type_1' => 'By Heat Formula',
	'setting_functions_heatthread_type_2' => 'By Participant Count',
	'setting_functions_heatthread_type_2_comment' => 'By Participant Count',
	'setting_functions_heatthread_period' => 'User Heat Value Period (days)',
	'setting_functions_heatthread_period_comment' => 'In days, a user who participates in a thread multiple times within one period only adds heat once. 0 means no period is set, heat increases by 1 for each participation. To avoid users gaming heat, it is recommended not to set to 0. (Replies, comments, reviews, favorites, shares, etc. all count as thread participation actions)',
	'setting_functions_heatthread_guidelimit' => 'Heat Value Aggregation Lower Limit',
	'setting_functions_heatthread_guidelimit_comment' => 'Lower limit of heat value when collecting hot threads in the guide function, default value "3"',
