	'setting_functions_heatthread_recommend_comment' => 'Thread heat increment each time a thread is rated, default value "3"',
	'setting_functions_heatthread_iconlevels' => 'Hot Thread Display Level',
	'setting_functions_heatthread_iconlevels_comment' => 'Set the heat index corresponding to each level of thread icons on the thread list page. Default is 3 levels, please separate with commas, e.g.: "50,100,200" means when thread heat is greater than 50 it is level 1, greater than 100 it is level 2, greater than 200 it is level 3. Leave blank to not show icons',
	'setting_functions_recommend' => 'Thread Rating',
	'setting_functions_recommend_tips' => '<li>Thread rating impact values vary for members of different user groups. You can set them in "Post Related" of "User Group" settings.</li>',
	'setting_functions_recommend_status' => 'Enable Thread Rating',
	'setting_functions_recommend_status_comment' => 'Thread rating is an important indicator for users to participate in thread heat. You can set the number of ratings users are allowed to perform each day',
	'setting_functions_recommend_addtext' => 'Plus Operation Text',
	'setting_functions_recommend_addtext_comment' => 'Set the text for positive rating, should not be too long. Recommended to use "Like", "Support"',
	'setting_functions_recommend_subtracttext' => 'Minus Operation Text',
	'setting_functions_recommend_subtracttext_comment' => 'Set the text for negative rating, should not be too long. Recommended to use "Dislike", "Oppose"',
	'setting_functions_recommend_defaultshow' => 'Hide Thread Rating Index',
	'setting_functions_recommend_defaultshow_comment' => 'Set whether to hide the rating result value of threads',
	'setting_functions_recommend_defaultshow_0' => 'Yes',
	'setting_functions_recommend_defaultshow_1' => 'No',
	'setting_functions_recommend_daycount' => 'Number of Thread Ratings per 24 Hours',
