	'setting_functions_recommend_ownthread' => 'Allow Rating Own Posts',
	'setting_functions_recommend_ownthread_comment' => 'Set whether to allow rating your own threads. Rating your own threads gives no credit reward',
	'setting_functions_recommend_iconlevels' => 'Rating Icon Display Level',
	'setting_functions_recommend_iconlevels_comment' => 'Set the rating index corresponding to each level of rating icons on the thread list page. Recommended 3 levels, please separate with commas, e.g.: "0,100,200" means when thread rating index is greater than 0 it is level 1, greater than 100 it is level 2, greater than 200 it is level 3. Threads of level 1 and above will be listed in "View positively rated threads" on the thread list page. Leave blank or 0 to not show icons',
	'setting_functions_comment' => 'Post Comment',
	'setting_functions_comment_allow' => 'Post Comment Method',
	'setting_functions_comment_allow_comment' => 'Set the comment posting method. If not selected, the comment function is disabled. Enabling any comment method requires setting comment permissions in user groups<br />"Direct comment" means posting comments through the "Comment" link in each floor of the post<br />"Floor reply" means automatically generating a comment on that floor when posting a reply through the "Reply" link in each floor of the post<br />Note: Clicking the "Reply" link in the thread will not generate a comment on the thread',
