	'setting_functions_comment_commentitem_3_comment' => 'One opinion per line. If there is a blank line, the content below the blank line will be displayed in the dropdown menu as alternative opinions',
	'setting_functions_comment_commentitem_4' => 'Activity Thread Comment Preset Views',
