	'setting_functions_login' => 'Login Settings',
	'setting_functions_other' => 'Other',
	'setting_functions_other_uidlogin' => 'Enable UID Login',
	'setting_functions_other_uidlogin_comment' => 'Select "Yes" to allow login verification via UID during site login',
	'setting_functions_other_secmobilelogin' => 'Enable Security Mobile Number Login',
	'setting_functions_other_secmobilelogin_comment' => 'Select "Yes" to allow login verification via secure mobile number or international calling code-secure mobile number during site login',
	'setting_functions_other_autoidselect' => 'Enable Auto-select Account on Login',
	'setting_functions_other_autoidselect_comment' => 'Select "Yes" to automatically match in order of UID, E-mail, username during site login. UID verification is only effective after UID login method is enabled',
	'setting_functions_other_submitlock' => '<span class="spectitle">Enable Form Anti-concurrency Feature</span>',
	'setting_functions_other_submitlock_comment' => 'Select "Yes" to prevent users from submitting forms multiple times at the same time, effectively preventing possible credit farming issues. Note: Without using memory cache (Redis, Memcached), this function may increase server load',
	'setting_functions_other_rssstatus' => '<span class="spectitle">Enable RSS</span>',
	'setting_functions_other_rssstatus_comment' => 'Select "Yes" to allow users to receive the latest post and article updates using RSS client software. Note: With many categories, this function may increase server load',
	'setting_functions_other_rssttl' => '<span class="spectitle">RSS TTL (minutes)</span>',
	'setting_functions_other_rssttl_comment' => 'TTL (Time to Live) is an attribute of RSS 2.0, used to control the auto-refresh time of subscribed content. The shorter the time, the higher the real-time nature of the data, but it increases server load. Usually can be set to a value within 30~180',
	'setting_functions_other_oltimespan' => '<span class="spectitle">User Online Time Update Duration (minutes)</span>',
	'setting_functions_other_oltimespan_comment' => 'Discuz! can count total and current month online time for each user. This setting sets the frequency of updating user online time. For example, if set to 10, the record updates every 10 minutes the user is online. The smaller the setting value, the more accurate the statistics, but the more resources consumed. Recommended within 5~30 range, 0 means no user online time recording',
	'setting_functions_other_debug' => 'Show Program Runtime Information',
	'setting_functions_other_debug_comment' => 'Select "Yes" to display program running time and database query count in the footer',
