	'setting_functions_other_at_anyone_comment' => 'Select No means it is only effective when the @mentioned person is in the user\'s follow list and friends',
	'setting_functions_other_chatpmrefreshtime' => 'Group Chat Message Auto-refresh Interval (seconds)',
	'setting_functions_other_chatpmrefreshtime_comment' => 'Used for group chat message content refresh. Shorter interval means greater server pressure. 0 means no refresh',
