	'setting_credits' => 'Credit Settings',
	'setting_credits_base' => 'Basic Settings',
	'setting_credits_scheme_title' => 'Credit Setting Scheme',
	'setting_credits_scheme' => 'Credit Setting Scheme',
	'setting_credits_extended' => 'Extended Credits Settings',
	'setting_credits_extended_comment' => 'The exchange ratio is the value of a single credit corresponding to one unit of standard credit. For example, if extcredits1 has a ratio of 1.5 (equivalent to 1.5 units of standard credit), extcredits2 has a ratio of 3 (equivalent to 3 units of standard credit), and extcredits3 has a ratio of 15 (equivalent to 15 units of standard credit), then 1 point of extcredits3 is equivalent to 5 points of extcredits2 or 10 points of extcredits1. Once the exchange ratio is set, users can exchange various credits with exchange ratios set in the User Center. If you do not want free credit exchange, set the exchange ratio to 0',
	'setting_credits_ratio' => 'Exchange Ratio',
	'setting_credits_lower_limit' => 'Credit Lower Limit',
	'setting_credits_init' => 'Initial Credits',
	'setting_credits_available' => 'Enable',
	'credits_img' => 'Credit Icon',
	'setting_credits_show_in_thread' => 'Show in Posts',
	'setting_credits_export' => 'Allow Exchange Out',
	'setting_credits_export_comment' => 'Set whether this credit is allowed to be exchanged for other credits',
	'setting_credits_import' => 'Allow Exchange In',
	'setting_credits_import_comment' => 'Set whether other credits are allowed to be exchanged for this credit',
	'setting_credits_policy_name' => 'Strategy Name',
	'setting_credits_policy_lowerlimit' => 'Credit Strategy Lower Limit',
	'setting_credits_policy_lowerlimit_comment' => 'When the user\'s credit is below this lower limit, the user will be prohibited from performing operations that involve deducting this credit in the credit strategy. For example, if set to -100 and "Search" deducts 10 units of this credit, when the user\'s credit is less than -100, they can no longer perform the "Search" operation',
	'setting_credits_policy' => 'Credit Strategy',
	'setting_credits_policy_comment' => 'The allowed range for each credit increase/decrease is -99~+99. If you set credit strategies for more operations, the system needs to update user credits more frequently, which means consuming more system resources. Therefore, please set according to actual situation. <a href="home.php?mod=spacecp&ac=credit&op=rule" target="_blank">View Credit Rules</a>',
	'setting_credits_policy_post' => 'Post Thread (+)',
	'setting_credits_policy_post_comment' => 'Credits increased when author posts a new thread. If the thread is deleted, the author\'s credits will be reduced accordingly by this standard',
	'setting_credits_policy_reply' => 'Reply (+)',
	'setting_credits_policy_reply_comment' => 'Credits increased when author posts a new reply. If the reply is deleted, the author\'s credits will be reduced accordingly by this standard',
	'setting_credits_policy_digest' => 'Add Digest (+)',
	'setting_credits_policy_digest_comment' => 'Credits increased for per-level author when thread is added to digest (multiplied by 1~3 according to digest level). If the thread is removed from digest, the author\'s credits will be reduced accordingly by this standard',
	'setting_credits_policy_postattach' => 'Upload Attachment (+)',
	'setting_credits_policy_postattach_comment' => 'Credits increased for each attachment uploaded by a user. If the attachment is deleted, the poster\'s credits will be reduced accordingly by this standard',
	'setting_credits_policy_getattach' => 'Download Attachment (-)',
	'setting_credits_policy_getattach_comment' => 'Credits deducted for each attachment downloaded by a user. Note: If the guest group is allowed to download attachments, this strategy may be bypassed',
	'setting_credits_policy_tradefinished' => 'Successful Transaction (+)',
	'setting_credits_policy_tradefinished_comment' => 'Credits increased after each successful transaction by a user',
	'setting_credits_policy_sendpm' => 'Send PM (-)',
	'setting_credits_policy_sendpm_comment' => 'Credits deducted for each PM sent by a user',
	'setting_credits_policy_votepoll' => 'Participate in Poll (+)',
	'setting_credits_policy_votepoll_comment' => 'Credits increased after each poll participation by a user',
	'setting_credits_policy_search' => 'Search (-)',
	'setting_credits_policy_search_comment' => 'Credits deducted for each search performed by a user',
	'setting_credits_policy_promotion_visit' => 'Visit Promotion (+)',
	'setting_credits_policy_promotion_visit_comment' => 'Credits earned by the promoter when a visitor accesses the site through a promotion link provided by the user (e.g. forum.php?mod=index&fromuid=1, ?fromuser=username)',
	'setting_credits_policy_promotion_register' => 'Registration Promotion (+)',
	'setting_credits_policy_promotion_register_comment' => 'Credits earned by the promoter when a visitor accesses the site through a promotion link provided by the user (e.g. forum.php?mod=register&fromuid=2, ?fromuser=username) and registers as a new member',
