	'setting_credits_formula_polls' => 'Poll Count',
	'setting_credits_formula_sharings' => 'Share Count',
	'setting_credits_formula_extcredits' => 'Custom Credits',
	'setting_credits_formula_comment' => 'Total credits are the only criterion for measuring user levels. You can set the user\'s total credit calculation formula here, where posts represents post count (threads + replies); threads represents number of threads posted by user; digestposts represents number of digest posts; oltime represents user\'s total online time (hours); friends represents friend count; doings represents number of doings posted; blogs represents number of blogs posted; albums represents number of albums uploaded; sharings represents number of shares posted; extcredits1~extcredits8 represent the 8 custom credits above. Operators including + - * / () can be used in the formula',
	'setting_credits_trans' => 'Transaction Credit Settings',
	'setting_credits_trans_comment' => 'Transaction credits are a type of credit that can be transferred between users, used for buy/sell transactions, and for posting reward threads. You can specify one credit as transaction credit. If no transaction credit is specified, the inter-user credit transaction function cannot be used. Note: Transaction credits must be enabled credits. Once determined, try not to change them, otherwise past records and transactions may have issues',
	'setting_credits_trans_credits' => 'Use Total Credits',
