	'setting_credits_trans5_none' => 'No Credits Used',
	'setting_credits_trans6' => 'Credits Used for Space Consumption',
	'setting_credits_trans6_comment' => 'Set the credit type used for consumption in space',
	'setting_credits_trans8' => 'Credits Used for User Report Rewards and Penalties',
