	'setting_credits_trans10' => 'Credits Used for Reply Rewards',
	'setting_credits_trans10_comment' => 'Credits used for reply rewards that can be set when users post threads',
	'setting_credits_trans11' => 'Sofa Grab Post Credit Limit',
	'setting_credits_trans11_comment' => 'Credits used when participating in sofa grab post credit limit',
	'setting_credits_trans12' => 'Credits Consumed for Creating Group',
	'setting_credits_trans12_comment' => 'Credits Consumed When Creating Groups',
	'setting_credits_trans13' => 'Credits Used for User Name Change',
	'setting_credits_trans13_comment' => 'Credits used when users change their username',
	'setting_credits_tax' => 'Credit Transaction Tax',
	'setting_credits_tax_comment' => 'Credit transaction tax (loss rate) is the tax rate deducted when users transfer, exchange, buy and sell credits. It is a floating point number between 0 and 1. For example, if set to 0.2, when a user converts 100 units of credits, the lost credits will be 20 units. 0 means no loss',
	'setting_credits_mintransfer' => 'Minimum Transfer Balance',
	'setting_credits_mintransfer_comment' => 'The minimum balance a user must have after credit transfer. With this feature, you can set a large balance limit so that users with credits less than this value cannot transfer; you can also set the balance limit to a negative number so that transfers can overdraw within the limit',
	'setting_credits_minexchange' => 'Minimum Exchange Balance',
	'setting_credits_minexchange_comment' => 'The minimum balance a user must have after credit exchange. With this feature, you can set a large balance limit so that users with credits less than this value cannot exchange; you can also set the balance limit to a negative number so that exchanges can overdraw within the limit',
	'setting_credits_maxincperthread' => 'Maximum Income per Thread (Attachment)',
	'setting_credits_maxincperthread_comment' => 'Set the maximum after-tax credit income for the author of a single thread (attachment) sale. After exceeding this limit, the buyer will still be deducted the corresponding credits, but the thread (attachment) author\'s earnings will no longer increase. This limit only applies to thread (attachment) sales, 0 means no limit',
	'setting_credits_maxchargespan' => 'Maximum Sale Time Limit per Thread (Attachment) (hours)',
	'setting_credits_maxchargespan_comment' => 'Set the maximum time a thread (attachment) can be sold from its publication time when sold by the author. After exceeding this time limit, it will become a regular thread (attachment), readers do not need to pay credits to purchase, and the author will no longer receive corresponding earnings. In hours, 0 means no limit',

