	'setting_mail_seccode' => 'Email Verification Code',
	'setting_mail_seccode_title' => 'Email Verification Code Introduction',
	'setting_mail_seccode_tips' => '<li>The <strong>email verification code</strong> function is similar to <strong>SMS verification code</strong>. Related functions will send a random letter/number verification code to the user\'s set secure email for identity verification;</li><li>The main application scenarios of the <strong>email verification code</strong> function are currently: account management identity verification.</li>',


	'setting_sec' => 'Basic Settings',
	'setting_seccheck' => 'Verification Settings',
	'setting_accountguard' => 'Account Bodyguard',
	'setting_sec_code_tips' => '<li>Use images as verification code text. The images must contain 24 characters "2346789BCEFGHJKMPQRTVWXY", and must be GIF transparent images with transparent background and black foreground. Black is the first index color of the image. Image size is not limited, but it is recommended that the width is not greater than 1/4 of the verification code width and the height is not greater than the verification code height. After creation, create a new subdirectory under source/data/seccode/gif/ with any name, and upload the 24 GIF images to the new subdirectory</li><li>Use images as the background of the verification code. Upload the prepared JPG images to the source/data/seccode/background/ directory, and the site will randomly use the images inside as the background of the verification code</li><li>Use TTF fonts as verification code text. Upload the downloaded TTF English font files to the source/data/seccode/font/en/ directory, and the site will randomly use the font files inside as the verification code text</li><li>Before using Chinese image verification code, you need to upload TTF Chinese font files containing complete Chinese characters to the source/data/seccode/font/ch/ directory, and the site will randomly use the font files inside as the verification code text</li><li>System verification codes are located in the source/class/seccode/ directory, plugin verification codes are located in the source/plugin/plugin_directory/seccode/ directory.</li>',
	'setting_sec_qaa_tips' => '<li>Q&A verification should be concise, unambiguous, and correctly answerable by normal people. Please frequently update verification questions and answers to prevent guessing!</li><li>System security verification components are located in the source/class/secqaa/ directory. Plugin security verification components are located in the source/plugin/plugin_directory/secqaa/ directory. Plugin security verification scenarios are located in the source/plugin/plugin_directory/seccheck/ directory.</li><li>New security verification components require memory cache (such as Redis) to be enabled, please configure.</li><li>Plugin developers must carefully read the content in <a href="https://open.dismall.com/?!devdoc" target="_blank">Discuz! Technical Documentation</a> before designing new verification Q&A scripts.</li>',

	'setting_sec_seclevel' => 'Security Verification Mode',
	'setting_sec_seclevel_comment' => 'Normally, we recommend using advanced verification mode. When many users on your site have trouble passing the verification code, you can use normal verification mode',
	'setting_sec_seclevel_lower' => 'Normal Verification Mode',
	'setting_sec_seclevel_higher' => 'Advanced Verification Mode',

	'setting_sec_base' => 'User Settings',
