	'setting_sec_base_security_verify_comment' => 'When this function is enabled, users need to perform security verification before performing various operations in Frontend Settings - Account Management - Security Settings. If multiple options are checked, users can choose the verification method on the frontend. If none are checked, no verification is required. <br/> To use the "Verify Secure Mobile" function, please in <a href="'.ADMINSCRIPT.'?action=smsgw"><strong>SMS Service</strong></a> settings to configure the SMS gateway and related parameters.<br/> To use the "Verify Security Email" function, please in <a href="'.ADMINSCRIPT.'?action=setting&operation=mail"><strong>Mail Settings</strong></a> to enable email service, and in <a href="'.ADMINSCRIPT.'?action=setting&operation=mail&anchor=seccode"><strong>Email Verification Code</strong></a> to set parameters related to sending email verification codes.',
