	'setting_sec_seccode_animator_disabled' => 'Your space does not support writing GIF files, cannot enable this function',
	'setting_sec_seccode_ttf' => 'Random TTF Font',
	'setting_sec_seccode_ttf_comment' => 'Select "Yes" to randomly use TTF font files in the source/data/seccode/font/en/ directory to generate verification code text. Select "No" to randomly use GIF images in the source/data/seccode/gif/ directory to generate verification code text. Chinese image verification code will randomly use TTF font files in the source/data/seccode/font/ch/ directory, no need for this setting',
