	'setting_datetime_autotz_comment' => 'Can automatically adjust the default timezone based on the user\'s IP address',

	'setting_datetime_periods' => 'Time Period Settings',
	'setting_datetime_visitbanperiods' => 'Forbidden Access Time Period',
	'setting_datetime_visitbanperiods_comment' => 'Users cannot access the site during this time period each day. Please use 24-hour time format. One time period per line. Can cross midnight if needed. Leave blank for no restriction. Example:<br />Daily 11:25 PM to 5:05 AM next day can be set as: <i>23:25-5:05</i><br />Daily 9:00 AM to 2:30 PM can be set as: <i>9:00-14:30</i><br />Note: Incorrect format may cause unexpected problems. If "Not restricted by time period" option is enabled in a user group, that group will not be constrained by any time period settings. All time period settings are based on the site\'s default timezone and are not affected by user-customized timezones',
	'setting_datetime_postbanperiods' => 'Forbidden Posting Time Period',
	'setting_datetime_postbanperiods_comment' => 'Users cannot post during this time period each day. Please use 24-hour time format. One time period per line. Can cross midnight if needed. Leave blank for no restriction. Example:<br />Daily 11:25 PM to 5:05 AM next day can be set as: <i>23:25-5:05</i><br />Daily 9:00 AM to 2:30 PM can be set as: <i>9:00-14:30</i><br />Note: Incorrect format may cause unexpected problems. If "Not restricted by time period" option is enabled in a user group, that group will not be constrained by any time period settings. All time period settings are based on the site\'s default timezone and are not affected by user-customized timezones',
	'setting_datetime_postmodperiods' => 'Post Moderation Time Period',
	'setting_datetime_postmodperiods_comment' => 'User posts are not displayed directly during this time period each day. They require manual moderation by moderators or administrators before publishing. Format and usage are the same as above',
	'setting_datetime_postignorearea' => 'List of Regions Where Posting is Not Time-restricted',
	'setting_datetime_postignorearea_comment' => 'When users are from addresses in this list, posting is not restricted by time periods. One region per line, e.g. "Beijing" (without quotes), leave blank for no setting.<br />Note: To accurately determine the region of your IP address, please download the qqwry.dat IP address database file online and upload it to the "source/data/ip/" directory, renamed as wry.dat',
	'setting_datetime_postignoreip' => 'List of IPs Where Posting is Not Time-restricted',
	'setting_datetime_postignoreip_comment' => 'When users are from IP addresses in this list, posting is not restricted by time periods. One IP per line, you can enter full address or just IP prefix, e.g. "192.168." (without quotes) matches all addresses in 192.168.0.0～192.168.255.255 range, leave blank for no setting',
	'setting_datetime_searchbanperiods' => 'Forbidden Full-text Search Time Period',
	'setting_datetime_searchbanperiods_comment' => 'Users cannot use full-text search during this time period each day. Format and usage are the same as above',
	'setting_datetime_ban_downtime' => 'Forbidden Attachment Download Time Period',
	'setting_datetime_ban_downtime_comment' => 'Users cannot download attachments during this time period each day. Format and usage are the same as above',

	'setting_sec_accountguard_forcelogin' => 'Secure Login',
