	'setting_sec_accountguard_postqqonly' => 'Posting Requires QQ Binding',
	'setting_sec_accountguard_postqqonly_comment' => 'When enabled, users must bind QQ number before posting',
	'setting_sec_accountguard_loginpwcheck' => 'Weak Password Login Detection',
	'setting_sec_accountguard_loginpwcheck_comment' => 'Action when the password strength used by the user during login does not meet the settings in "Global > Registration & Access Control > Registration > Password Complexity Requirement". If forced change is enabled, weak password accounts will be temporarily frozen and automatically unfrozen after successful password change',
	'setting_sec_accountguard_loginpwcheck_none' => 'Disabled',
	'setting_sec_accountguard_loginpwcheck_prompt' => 'Enable and Prompt',
	'setting_sec_accountguard_loginpwcheck_force' => 'Enable and Force Weak Password Change',
	'setting_sec_accountguard_loginoutofdate' => 'Abnormal Login Detection',
	'setting_sec_accountguard_loginoutofdate_comment' => 'When the time since the user\'s last login exceeds a certain period, the account will enter the unverified group. Users can unfreeze their account by verifying their email or appealing <a href="'.ADMINSCRIPT.'?action=moderate&operation=members">Moderate Users</a>',
	'setting_sec_accountguard_loginoutofdatenum' => 'Abnormal Login Detection Days',
