	'setting_attach_image_lib' => 'Image Processing Library Type',
	'setting_attach_image_lib_comment' => 'Please select the image processing library used by Discuz! for thumbnails and watermarks. GD is the most widely used library but uses more system resources. ImageMagick is fast and uses less system resources, but is relatively less secure and requires the server to install the ImageMagick extension. If your server can install this program, please download from <a href="http://www.imagemagick.org" target="_blank">http://www.imagemagick.org</a>',
