	'setting_imgwater_image_watermarktype' => 'Watermark Image Type',
	'setting_imgwater_image_watermarktype_comment' => 'If setting a GIF type file as watermark, the watermark image is static/image/common/watermark.gif. If setting a PNG type file as watermark, the watermark image is static/image/common/watermark.png. You can replace the watermark file to achieve different watermark effects. If setting text type watermark and using GD image processing library, FreeType library support is also required',
