	'setting_imgwater_image_watermarktype_png' => 'PNG Type Watermark',
	'setting_imgwater_image_watermarktype_text' => 'Text Type Watermark',
	'setting_imgwater_image_watermarktrans' => 'Watermark Opacity',
	'setting_imgwater_image_watermarktrans_comment' => 'Set the opacity of GIF type watermark image and original image, range is integer 1～100. Larger value means less transparent watermark. PNG type watermark has true color transparency effect itself, no need for this setting. This function is only effective after enabling watermark function',
	'setting_imgwater_image_watermarkquality' => 'JPEG Watermark Quality',
	'setting_imgwater_image_watermarkquality_comment' => 'Set the quality parameter of JPEG type image attachments after adding watermark, range is integer 0～100. Larger value means better image quality but larger file size. This function is only effective after enabling watermark function',
	'setting_imgwater_image_watermarktext_text' => 'Text Watermark Text',
	'setting_imgwater_image_watermarktext_text_comment' => 'If the TrueType font you specify is a Chinese font file, you can write Chinese in the text watermark',
