	'setting_imgwater_image_watermarktext_fontpath_comment' => 'Enter the TTF font file stored in source/data/seccode/font/ch/ or source/data/seccode/font/en/ directory, supports Chinese fonts. If using Chinese TTF font, please use a font file containing complete Chinese characters',
	'setting_imgwater_image_watermarktext_size' => 'Text Watermark Font Size',
