	'settings_sphinx_sphinxrank_comment' => '(1)SPH_RANK_PROXIMITY_BM25, default mode, uses both phrase scoring and BM25 scoring, and combines the two. [Default]
<br />(2)SPH_RANK_BM25, statistical relevance calculation mode, only uses BM25 scoring (same as most full-text search engines). This mode is faster, but may reduce the quality of results for queries containing multiple words.
<br />(3)SPH_RANK_NONE, mode with scoring disabled, this is the fastest mode. In fact this mode is the same as Boolean search. All matches are assigned a weight of 1',

