	'setting_uc' => 'UCenter Settings',
	'setting_uc_tips' => '<li>These settings are automatically generated during site installation. Normally please do not modify. Before modifying, please backup config/config_ucenter.php file to prevent site malfunction due to incorrect modifications</li>',
	'setting_uc_linkstatus' => 'Communication Status',
	'setting_uc_linkstatus_correct' => 'Communication Successful',
