	'setting_uc_key_comment' => 'Communication key is used for encrypting information transmission between UCenter and Discuz!, can contain any letters and numbers. Please set exactly the same communication key in UCenter and Discuz! to ensure normal communication between the two systems',
	'setting_uc_api' => 'UCenter Access URL',
	'setting_uc_api_comment' => 'If your UCenter access URL has changed, please modify this item. Incorrect settings may cause site function abnormalities, please modify carefully. <br />Format: http://www.sitename.com/uc_server (do not add trailing \'/\')',
