	'setting_uc_fastactivation_comment' => 'Select "Yes" for auto-activation on user login; select "No" to allow user activation but required fields in registration settings must be filled',
	'setting_uc_avatarmethod' => 'Avatar Call Method',
	'setting_uc_avatarmethod_comment' => 'Set the calling method for user avatars
		<br />Dynamic mode: Relies on the server to return avatar URLs, server load increases when there are many avatars
		<br />Static mode: Returns a fixed static avatar URL, does not check if the avatar exists, loads default avatar on failure
		<br />Browser loading mode: Loads the static avatar URL through the browser, automatically fetches default avatar on failure',
