	'forums_edit_tips' => '<li>The following settings are not inheritable, i.e., only effective for the current forum, will not affect sub-forums.</li>',
	'forums_edit_perm_tips' => '<li>1. Multiple conditions within each permission type (group, verify, etc.) have an "OR" relationship;</li>
<li>2. After setting a "Permission Assertion Expression" for the same function (browsing forums, posting new threads, etc.), the condition judgment for that function is based on the "Permission Assertion Expression", and the checked content no longer takes effect;</li>
<li>3. Within the same permission type (group, verify, etc.) for the same function (browsing forums, posting new threads, etc.), when multiple detection conditions are checked, the default relationship between conditions is "OR", i.e.: meeting any one condition is considered passing; if you need to judge that multiple selected conditions must all be true, please check the "All must be satisfied" option below;</li>
<li>4. For more complex condition judgments, please use "Permission Assertion Expression" to write rules, such as cross-permission type condition judgments, coexistence of and and or, etc.</li>',
