	'forums_edit_threadtypes_tips' => '<ul><li>"Thread Category" is used to categorize threads in sub-forums. When publishing a new thread, the author can categorize the thread according to preset types; users can also browse by category in the forum (needs to be set in "Edit Forum"). Different from the sub-forum function, thread categories are only used to categorize posts in a specific forum, suitable for situations with high relevance and needing some kind of classification.</ul><ul><li>"Thread Category" is shared across the entire forum. You can set which types the current forum uses for thread categorization in "Edit Forum".</ul><ul><li>If you rename, delete, or modify the display order of certain thread categories, please edit the forum associated with this category (no changes needed) and submit, so that the thread category can be updated.</ul>',
