	'threadtype_infotypes_btemplate' => 'Category Info Module Call Display Template',
	'threadtype_infotypes_template_tips' => '<li>If the template is empty, the system default template is used.</li><li>Click the [Insert Template] link above to insert related code into the template, then you can edit with web editing tools like DreamWeaver or manually.</li><li>Category info display templates support HTML, where {field variable name} represents the field name, and [field variable name] represents the specific value of the field.<br />For example, there is a field variable named age, field name is Age, and the value filled in by the member is 20. Then the string {age}[agevalue] will display as "Age 20" in the template.</li>',
