	'threadtype_edit_select_choices' => 'Field Content',
	'threadtype_edit_select_choices_comment' => 'Only effective when the item is optional, one field per line, before the equals sign is the field index (numbers recommended), after is the content, e.g.: <br /><i>1 = Optical mouse<br />2 = Mechanical mouse<br />3 = No mouse</i><br /><i>1.1 = Black optical mouse</i><br /><i>1.2 = Red optical mouse</i><br /><i>1.2.1 = Bluetooth red optical mouse</i><br />Note: <br />1. "1.2.1 = Bluetooth red optical mouse" must have both "1.2 = Red optical mouse" and "1 = Optical mouse"<br />2. No spaces between "1.2.1"<br />3. After fields are determined, please do not modify the correspondence between indexes and content, but you can still add new fields. To change the display order, you can move the entire line up or down',
	'threadtype_edit_choices' => 'Field Content',
	'threadtype_edit_choices_comment' => 'Only effective when the item is optional. One field per line, field index before the equals sign (recommended to use numbers), content after. For example: <br /><i>1 = Optical Mouse<br />2 = Mechanical Mouse<br />3 = No Mouse</i><br />Note: After the field is determined, please do not modify the correspondence between index and content, but you can still add new fields. If you need to change the display order, you can do so by moving the entire line up or down',
