	'founder_patch_tips' => '<li>Vulnerability fix status description:</li>
							<li>
								<em class="fixed">&nbsp;2</em> File may have been modified, no vulnerability found<br />
								<em class="fixed">&nbsp;1</em> Fix completed<br />
								<em class="unfixed">&nbsp;0</em> Not fixed<br />
								<em class="unfixed">-1</em> Vulnerability code is empty, your local vulnerability information data may have problems<br />
								<em class="unfixed">-2</em> Vulnerability patch file does not exist or file cannot be modified, please check and change permissions to readable and writable (777)<br />
								<em class="unfixed">-3</em> Error writing temporary file, please check if the data directory is writable<br />
								<em class="unfixed">-4</em> FTP method cannot be used, please confirm that FTP account and other related information are filled in correctly<br />
								<em class="unfixed">-5</em> Problem copying files, please confirm that the source code file directory and subdirectories are readable and writable, or files may be locked, please close the site before operating<br />
								<em class="unfixed">-6</em> Problem fixing vulnerability, problem during rollback, please restore the file as soon as possible, file backup can be found in the same directory
							</li>',

