	'usergroups_tips' => '<li>User groups are divided into system groups, member groups, and custom groups. Custom user groups can be set as multiple promotion user groups. Member groups and promotion groups determine group and permissions by credits. Other groups are manually set and will not be automatically changed by the system.</li><li>System groups and non-promotion group settings do not require specifying credits. Discuz! reserves 8 system titles from site administrator to guest. Users of non-public user groups cannot join on their own and must be manually added by administrators.</li><li>Member user groups are divided into at least two groups, with credit lower limits of negative value (any negative number) and 0 respectively. Otherwise, some users will not be able to match user groups.</li><li>Promotion user groups are divided into at least two groups, with credit lower limit of 0. Otherwise, some users will not be able to match user groups.</li>',
