	'usergroups_edit_system' => 'User Group System',
	'usergroups_edit_system_tips' => '<li><b><u>Promotion User Group</u></b><br />When a user group is set as "Promotion User Group", you can set a starting user group and multiple subordinate user groups, then set the credit range on the user group list page.</li><li><b><u>Non-Public User Group</u></b><br />When a user group is set as "Non-Public User Group", whether in the form of primary user group or extended user group, users can only be manually added to this group by administrators.</li><li><b><u>Public User Group</u></b><br />When this user group is set as "Public User Group", and the user\'s current user group is allowed to join/leave public user groups, users can set this group as their primary user group or extended user group in the User Center. When set as primary user group, related permissions will follow this user group\'s permission settings; when set as extended user group, users can access specific forum sections that only this user group can access.</li><li><b>Paid Public User Group</b>: <br />You can choose to require users to pay a certain amount of trade credits to join this group. The amount of trade credits users pay determines how long the system allows them to have this group\'s permissions. You can set the amount of trade credits required for users to have this group\'s permissions for one day. After the period purchased by the user expires, the system will automatically remove the user\'s related user group attributes.</li><li><b>Free Public User Group</b>: <br />Users only need to choose to join this user group in the User Center to have the permissions and title of this user group without paying any price.</li>',
	'usergroups_edit_system_public' => 'Public User Group',
	'usergroups_edit_system_buy' => 'Paid User Group',
	'usergroups_edit_system_free' => 'Free User Group',
	'usergroups_edit_system_public_comment' => 'Set whether it is a public user group. Note: Before using this function, please determine if it is really needed. Otherwise, once users join this group on their own, even if you later set this group as a non-public user group, you still cannot batch remove users from this group, unless you delete this user group. Public user groups cannot be associated with management groups to avoid security risks',
	'usergroups_edit_system_dailyprice' => 'Paid Public User Group Daily Price',
	'usergroups_edit_system_dailyprice_comment' => 'If you need users to pay corresponding trade credits to join this user group, please enter the daily purchase price of this group here, in the unit used by trade credits. For example, if set to 2, users purchasing 30 days of this group\'s permissions need to pay 2*30=60 trade credits. After the 30-day validity period, the user will automatically exit from this group. If set to 0, this group is a free public user group. Note: This function is only effective after the user group is first set as a public user group and valid trade credits are set',
	'usergroups_edit_system_minspan' => 'Paid Public User Group Minimum Purchase Time (days)',
	'usergroups_edit_system_minspan_comment' => 'Set the minimum number of days of trade credits users must pay for at one time when purchasing this group\'s permissions. Please set to a value greater than or equal to 1. For example, if the daily price is 2 and the minimum purchase time is 10, users need to spend at least 2*10=20 trade credits to get at least 10 days of this group\'s permissions to join this group. Note: This function is only effective after the user group is first set as a paid public user group',
	'usergroups_edit_system_guest_portal_tips' => '<li>When setting guest user group, portal-related posting permissions are invalid for this user group</li>',
	'usergroups_edit_system_guest_home_tips' => '<li>When setting guest user group, space-related posting and comment permissions are invalid for this user group</li>',

