	'threads_postposition' => 'Post Optimization',
	'threads_postposition_tips' => '<li>This function is mainly used to optimize the display performance of threads with a large number of replies. Generally, when the number of post replies exceeds 5000 or it is expected that the number of replies to this post will be above 5000, you can add this thread to the optimization queue</li>
					<li>When a thread enters the optimization queue, we do not recommend deleting a specific post in that thread. If the content is indeed violating rules, we suggest you just block it</li>
					<li>When you launch a floor-grabbing activity, the system will automatically put the floor-grabbing thread into the optimization queue. You can also put any thread with many replies into the optimization queue here</li>
				',

	'threads_postposition_replies' => 'Specified Reply Count Greater Than',
