	'srch_tid' => 'Or directly specify thread tid =',

	'prune_tips' => '<li>Batch post deletion is only for deleting violating posts. If you need to batch delete old historical posts, please use the batch thread management function.</li><li>To use this function, you must provide at least one of start time and end time, and at least one of posting username, posting IP, and content keyword, for a total of at least two necessary conditions, otherwise the operation cannot be performed.</li><li>If the post that meets the deletion conditions is the first post of a thread, or if the thread has no replies, the entire thread will be deleted.</li><li>If you are not a forum administrator, you can only delete posts within the range from a certain time to the present.</li><li>The time range for super moderators to delete posts is two weeks (14 days); the time range for moderators is one week (7 days) and they can only delete posts in the forums they manage.</li><li>Keywords can use the qualifier {x} to limit the ignorable text between two adjacent characters, where x is the number of ignored characters. For example, "a{1}s{2}s" (without quotes) can search for "<b>ass</b>" and also search for "<b>a</b>x<b>s</b>x<b>s</b>" and "<b>a</b>x<b>s</b>xx<b>s</b>" etc.</li>',
