	'misc_mediacode_edit_tips' => '<li>Multimedia code parsing scripts are located in the source/class/media/ directory. Plugin scripts are located in the source/plugin/plugin_directory/media/ directory.</li><li>Plugin developers must carefully read the content in <a href="https://open.dismall.com/?!devdoc" target="_blank">Discuz! Technical Documentation</a> before designing new multimedia code scripts.</li>',
