	'misc_cron' => 'Cron Tasks',
	'misc_cron_list' => 'Cron Task List',
	'misc_cron_tips' => '<li>Cron tasks are a feature provided by Discuz! that enables the system to automatically execute certain specific tasks at specified times. When needed, you can also conveniently use them for site function expansion.</li><li>Cron tasks are features closely related to the system core. Improper settings may cause hidden dangers to site functions, and in severe cases may cause the site to not operate normally. Therefore, please only add or modify task items yourself when you fully understand cron task features and clearly know what you are doing and what consequences there will be.</li><li>Different from other functions, this function sets and displays time completely according to the site system default time zone, and will not change the displayed or set time value based on the time zone setting of a certain user or administrator.</li><li>Cron tasks use the user-triggered mechanism by default. If you want to switch to the system-triggered mechanism, please refer to the instructions in the /api/remote/cron.php file to set system cron tasks.</li>',
	'misc_cron_permonth' => 'Monthly',
	'misc_cron_perweek' => 'Weekly',
