	'misc_cron_edit' => 'Edit Cron Task',
	'misc_cron_edit_tips' => '<li>You are editing a system built-in cron task. Unless you are very familiar with Discuz! structure, it is strongly recommended not to modify the default settings.</li><li>Please record the original settings before modifying. Improper settings may cause unexpected errors on the site.</li>',
	'misc_cron_edit_weekday' => 'Weekly',
	'misc_cron_edit_weekday_comment' => 'Set which day of the week to execute this task, "*" means no limit. This setting will override the "Day" setting below',
	'misc_cron_edit_day' => 'Monthly',
	'misc_cron_edit_day_comment' => 'Set which day to execute this task, "*" means no limit',
	'misc_cron_edit_hour' => 'Hours',
	'misc_cron_edit_hour_comment' => 'Set which hour to execute this task, "*" means no limit',
	'misc_cron_edit_minute' => 'Minutes',
	'misc_cron_edit_minute_comment' => 'Set which minutes to execute this task, up to 12 minute values can be set, separate multiple values with half-width comma ",", leave blank for no restriction',
	'misc_cron_edit_filename' => 'Task Script',
	'misc_cron_edit_filename_comment' => 'Set the execution program file name for this task, please do not include the path. System cron tasks are located in the source/child/cron/ directory, plugin cron tasks are located in source/plugin/plugin_directory/cron/ directory',

	'misc_censor' => 'Word Censorship',
	'misc_censor_tips' => '<li>The content before replacement can use the qualifier {x} to limit the ignorable text between two adjacent characters, where x is the number of ignored bytes. For example, "a{1}s{2}s" (without quotes) can filter "<b>ass</b>" and also filter "<b>a</b>x<b>s</b>x<b>s</b>" and "<b>a</b>x<b>s</b>xx<b>s</b>" etc. For Chinese characters, if using GBK or Big-5 version, each Chinese character is equivalent to 2 bytes; if using UTF-8 version, each Chinese character is equivalent to 3 bytes.</li><li>To not affect program efficiency, please do not set too many unnecessary filter contents.</li><li>Moderation is only effective for content in the forum</li><li>If you are not a forum administrator, you can only edit or delete items you added.</li><li>If a sensitive word starts and ends with "/" (without quotes), it means the format is a regular expression. In this case, the replacement content can use "(n)" to reference subpatterns in the regex, e.g. "/1\d{10}([^\d]+|$)/" replaced with "mobile(1)".</li>',
	'misc_censor_word' => 'Sensitive Word',
	'misc_censor_replacement' => 'Filter Action',
	'misc_censor_type' => 'Word Category',
	'misc_censor_postlimit' => 'Post Count Limit',
	'misc_censor_wordtype_edit' => 'Edit Word Category',
	'misc_censor_wordtype_tips' => '<li>The default category is a built-in category. When a category is deleted, word filters will be automatically added to the default category.</li>',
	'misc_censor_batch_add' => 'Batch Add',
	'misc_censor_batch_add_tips' => '<li>One set of filter words per line, sensitive words and replacement words separated by "=";</li><li>If you want to prohibit posting text containing a certain word instead of replacing/filtering, set the corresponding replacement content to {BANNED}; if you want to automatically mark as requiring manual moderation when users post text containing a certain word, instead of directly displaying or replacing/filtering, set the corresponding replacement content to {MOD} (moderation is only effective for forum content).</li><li>If you just want to replace a word directly with **, just enter the word;</li><li>For example:<br />toobad<br />nobad<br />badword=good<br />sexword={BANNED}</li><li>Export/import supports word category import. When importing without a category, you can select the specified import category. If there is no category, it will be automatically classified into the default category</li>',
	'misc_censor_batch_add_clear' => 'Clear the current word list before importing new words. This operation cannot be undone. It is recommended to first <a href="'.ADMINSCRIPT.'?action=misc&operation=censor&do=export" target="_blank"><b><u>Export word list</u></b></a>, make a backup.<br />',
	'misc_censor_batch_add_overwrite' => 'Overwrite existing words with new settings',
	'misc_censor_batch_add_no_overwrite' => 'Do not import existing words',
	'misc_censor_word_banned' => 'Banned Keywords',
