	'smilies_edit_add_tips' => 'No unused smiley images found in directory {smurl}. Smiley image filenames only allow numbers, 26 English letters, underscores, half-width spaces, and symbols like <>-.&[](). Filename length cannot exceed 30 bytes, otherwise they will not be recognized. Please upload smiley images to add via FTP to the {smurl} directory, then click "Research"',
