	'smilies_prefix_tips' => 'Please enter smiley prefix and suffix. It is recommended to use symbols like [ ( : as prefix, and ] ) : as suffix',
	'smilies_id' => 'Smiley ID',
	'smilies_prefix' => 'Prefix',
	'smilies_suffix' => 'Suffix',
	'smilies_import' => 'Import Smileys',
	'smilies_tips' => '<li>To add smilies, please upload smiley images to the corresponding smiley directory (static/image/smiley/smiley_directory/).</li><li>Smilies support images in "JPG, GIF, PNG" formats. Filenames only allow numbers, 26 English letters, underscores, half-width spaces, and symbols like <>-.&[](). Filename length must not exceed 30 bytes, otherwise they will not be recognized.</li><li>Please do not set too many smilies to avoid occupying too much server resources.</li>',
	'smilies_tips_smileytypes' => '<li>Smiley export includes smiley category and smiley code information. Please download smiley image files via FTP.</li><li>Please do not enable too many smiley categories at the same time, and control the name length of smiley categories, so that the smiley window cannot fully display all smiley categories.</li><li>You can set the default displayed smiley category in interface style. To delete a smiley category, please delete all smileys under that category first.</li>',
	'smiliesupload_tips' => 'No unused smiley categories found. You can create smiley category directories via FTP in the static/image/smiley/ directory and upload smiley images, then refresh this page. Smiley category directory names only allow numbers, 26 English letters, and underscores',
