	'misc_stamp_listtips' => '<li>Verification stamps are displayed on the post content page, verification icons are displayed on the thread list page.</li><li>The system has reserved 100 thread verification image positions, with image IDs 0 to 99.</li><li>Do not modify image IDs arbitrarily, otherwise it will cause confusion of stamps and icons already used in threads.</li><li>When a stamp has a related operation set, the stamp will be automatically added to the thread when the corresponding operation is performed; when a stamp has a related icon set, the icon will be automatically added to the thread list when the stamp is added. Related operations and related icons cannot be set at the same time.</li>',
