	'editorblock' => 'JSON Editor Block',
	'editorblock_admin' => 'JSON Editor Block',
	'editorblock_admin_setting' => 'Settings',
	'editorblock_admin_list' => 'List',
	'editorblock_admin_list_tips' => '<li>This is used to manage the new JSON editor block settings.</li><li>When all are disabled, a basic "Text Paragraph" block function will be enabled by default, and the "Text Paragraph" block does not support sorting, displayed first by default.</li><li>The new JSON editor depends on Redis, please configure Redis first.</li>',
	'editorblock_type_message_0' => 'Data Type',
	'editorblock_type_message_1' => 'Image Type',
	'editorblock_type_message_2' => 'Attachment Type',
	'editorblock_type_message_3' => 'Video Type',
	'editorblock_type_message_4' => 'Audio Type',
	'editorblock_type_message_5' => 'File Type',
	'editorblock_nonexistence' => 'Editor block does not exist',
	'editorblock_name_invalid' => 'You have not filled in the editor block name',
	'editorblock_name_more' => 'Sorry, your editor block name exceeds 255 characters',
	'editorblock_order_invalid' => 'Invalid editor block sorting',
	'editorblock_parameter_null' => 'Editor block parameters cannot be empty',
	'editorblock_parameter_invalid' => 'Invalid editor block parameters',
	'editorblock_update' => '<span style="color: red;">Updating the editor block will overwrite the parsed template, CSS, and Config configuration content. Please back up your custom template code in advance!</span>',
	'editorblock_succeed' => 'Editor block configuration updated successfully',
	'editorblock_parametertip' => 'Current Block Parameters',
	'editorblock_csstip' => 'CSS Usage Tips',
	'editorblock_usage' => 'Tutorial',
	'editorblock_usage_content' => '<ul><li>Variable usage: "<span style="color: green;">{field_name}</span>", multi-level use "." to connect, e.g.: "<span style="color: green;">{field1.field2.field3}</span>"; </li><li>Variable usage examples: {id}, {type}, {data.alignment}, {data.items.text};</li><li>Supports "[loop]" loop, example block code: <pre>{
    "data": {
        ...
        "items": [
        	{
        		"text" : "abc"
        	},
        	{
        		"text" : "def"
        	},
        	...
        ]
    }
}</pre>
Loop usage: <pre>
&lt;ul&gt;
[loop data.items]
   &lt;li&gt;{text}&lt;/li&gt;
[/loop]
&lt;/ul&gt;
</pre>
<br/>
Loop index (put inside the loop body, auto count): <pre>
[loopindex]
</pre>
<br/>
Multi-column rendering (put inside the loop body, specify sub-data blocks, only for multi-column rendering): <pre>
[column blocks]
</pre>
<br/>
IF judgment method: <pre>
[if data.items=1]
   {text}block data variable or normal string
[/if]
</pre>
<br/>
URL to absolute URL: <pre>
[url data.file.url]
</pre>
<br/>
Get attachment aid encrypted string: <pre>
[attach data.file.aid]
</pre>
</li><li>CSS style code part must be strictly written inside &lt;style type="text/css"&gt;......&lt;/style&gt;.</li></ul>',

	'editorblock_usage_css_content' => '<ul><li>Global CSS styles will be loaded globally on content pages published by the JSON editor;</li><li>CSS style code part must be strictly written inside &lt;style type="text/css"&gt;......&lt;/style&gt;.</li></ul>',

	'card' => 'Recharge Card',
	'card_make_tips' => '<li>When generating card codes, simple rules or small generation counts may cause the actual generated count to be less than the preset count.</li>',
