	'card_config_open_comment' => 'Set whether to allow frontend recharge. Disabling frontend recharge function does not affect backend card password generation<br />Recharge card password verification code switch: <a href="'.ADMINSCRIPT.'?action=setting&operation=seccheck">Global->Security->Verification Settings</a>',
