	'card_number_unit' => 'bits',
	'card_make_rule' => 'Card Code Generation Rules',
	'card_make_rule_comment' => '"<strong>@</strong>" represents any random English character, "<strong>#</strong>" represents any random number, "<strong>*</strong>" represents any English letter or number<br />Card password rule sample: "DZ2011@@@@@#####*****"<br />Note: Too few rule digits will increase the probability of duplicate card password generation. Too many duplicate card passwords will cause card password generation to terminate<br />Card password rules cannot contain Chinese or other special symbols<br />To avoid duplicate card passwords, the number of random digits should preferably not be less than 8',
