	'tasks_tips' => '<li>Only tasks marked as "Available" can be accessed and applied for by members.</li>',
	'tasks_tips_edit' => '<li>Only when a task is marked as "Available" can members see and participate in it.</li><li>Tasks can have a start time set. You can schedule when a task starts. If not set, the task starts by default.</li>',
	'tasks_tips_add_member' => '<li>Member tasks currently include three types: adding friends, favoriting threads, using magic items. Such tasks are used to encourage and guide members to use certain forum features and liven up the forum atmosphere.</li><li>Setting different task completion conditions can create tasks suitable for your forum.</li>',
	'tasks_tips_add_post' => '<li>Post tasks currently include three types: posting new threads, posting new replies, posting new threads/replies.</li><li>If a post task specifies a forum, please pay attention to the permission settings of user groups and forums. Otherwise, some users who apply for the task may never complete it due to no permission to post in that forum.</li><li>For new reply tasks, you can specify replying to a certain thread or a certain author\'s threads, but please note that the thread must exist, otherwise users cannot complete the task.</li>',
	'tasks_tips_add_type' => '<li>System tasks are located in the source/class/task/ directory. Plugin tasks are located in the source/plugin/plugin_directory/task/ directory.</li><li>Plugin developers must carefully read the content in <a href="https://open.dismall.com/?!devdoc" target="_blank">Discuz! Technical Documentation</a> before designing new task types.</li>',
	'tasks_edit' => 'Edit Task',
	'tasks_list' => 'Task List',
	'tasks_edit_basic' => 'Edit Task Settings',
	'tasks_add' => 'Add Task',
	'tasks_add_basic' => 'Task Basic Settings',
	'tasks_add_name' => 'Task Name',
	'tasks_add_name_comment' => 'No more than 50 bytes',
	'tasks_add_desc' => 'Task Description',
	'tasks_add_desc_comment' => 'Detailed description of the task, supports HTML code',
	'tasks_add_icon' => 'Task Icon',
	'tasks_add_icon_comment' => 'Please upload the icon file to the static/image/task/ directory, just fill in the filename here. Leave blank to use the <a href="{defaulticon}" target="_blank">default icon</a>. Recommended icon file size is 64 x 64',
	'tasks_add_starttime' => 'Online Time',
	'tasks_add_starttime_comment' => 'Task start time, leave blank for immediate start',
	'tasks_add_endtime' => 'Offline Time',
	'tasks_add_endtime_comment' => 'Task end time. After ending, members cannot apply for this task. Leave blank for no limit',
	'tasks_add_periodtype' => 'Task Interval Cycle Unit',
	'tasks_add_periodtype_comment' => 'Set the calculation unit for task interval period<br />
		Hours: means can apply again after specified hours, fill in the number of hours for the interval period<br />
		Days: means can apply again after specified days, fill in the number of days for the interval period<br />
		Weeks: means can only apply again after specified time each week (Monday to Sunday), fill in numbers 1 (Monday) to 7 (Sunday) for the interval period<br />
		Months: means can only apply again after specified date each month, fill in numbers 1 to 29, 30, 31 for the interval period<br />',
	'tasks_add_periodtype_hour' => 'Hours',
	'tasks_add_periodtype_day' => 'Days',
	'tasks_add_periodtype_week' => 'Week',
	'tasks_add_periodtype_month' => 'Month',
	'tasks_add_period' => 'Task Interval Cycle',
	'tasks_add_period_comment' => 'Leave blank for one-time task, otherwise it is a periodic task',
	'tasks_add_reward' => 'Task Reward',
	'tasks_add_reward_comment' => 'Reward types include: credits, magic items, medals, and custom user groups. Among them, magic items and medals require the corresponding functions to be enabled',

