	'tasks_add_relatedtask' => 'Must Complete Specified Tasks',
	'tasks_add_relatedtask_comment' => 'Whether other tasks must be completed before applying for this task. Using this setting, you can design a series of tasks, usually no limit',
	'tasks_add_exclusivetask' => 'Must Not Have Claimed Specified Tasks',
	'tasks_add_exclusivetask_comment' => 'When the configured task is claimed and not abandoned, application or completion of this task is not allowed. Using this setting, you can design a series of tasks, usually no limit',
	'tasks_add_conditions' => 'Task Completion Conditions',
	'tasks_add_maxnum' => 'Maximum Applications',
	'tasks_add_maxnum_comment' => 'When the number of people who have completed this task reaches this value, the system will automatically reject new applications. 0 or leave blank for no limit',
	'tasks_add_limit_act' => 'Action',
	'tasks_add_limit_num' => 'Minimum Action Count',
