	'tasks_add_limit_time' => 'Time Limit (hours)',
	'tasks_add_limit_time_comment' => 'Set the time limit for members from applying to completing the task. If members fail to complete the task within this time, they cannot claim the reward and the task is marked as failed. 0 or leave blank for no limit',
	'tasks_add_limit_forumid' => 'Forum Restriction',
	'tasks_add_limit_forumid_comment' => 'Set that members can only complete the task in a specific forum',
	'tasks_add_limit_threadid' => 'Reply to Specified Thread',
