	'ec' => 'E-commerce',

	'ec_alipay' => 'Alipay Settings',
	'ec_alipay_on' => 'Whether to Enable Alipay',
	'ec_alipay_tips' => '<li>"Alipay" (<a href="http://www.alipay.com" target="_blank">http://www.alipay.com</a>) is China\'s leading online payment platform, founded by Alibaba, the world\'s best B2B company. It provides Discuz! users with credit purchase and forum B2C, C2C trading platforms. With simple settings, you can make forum content and popularity become an important profit source besides advertising revenue, thus realizing large-scale forum operation.</li><li><b>Due to cash transactions involved, to avoid financial losses caused by improper operation, please carefully read the e-commerce section in the User Manual before starting to use the Alipay credit transaction function (excluding the Alipay button function), and make related settings after confirming full understanding and acceptance of the relevant processes and usage methods.</b></li><li>Your use of Alipay services is based on complete voluntariness. Except for financial losses caused by Discuz! subjective malicious factors, Tencent Cloud shall not be liable for any losses caused by using this function.</li><li>Alipay customer service phone number is 95188.</li>',
	'ec_alipay_account' => 'Receiving Alipay Account',
	'ec_alipay_account_comment' => 'If you enable the exchange or transaction function, please fill in a valid Alipay account for receiving payments from users who exchange cash for transaction credits. If the account is invalid or the security code is wrong, it will result in users being unable to automatically recharge their credit accounts after payment, or conduct normal transactions to automatically recharge their credit accounts, or conduct normal transactions.<br />If you do not have an Alipay account, <a href="http://www.alipay.com/redir.do?id=307&site=allbbs&target=https%3A%2F%2Fwww.alipay.com%2Fuser%2Fuser_register.htm" target="_blank">please click here to register</a>',
	'ec_alipay_check_comment' => 'This test will simulate submitting an order of 0.01 RMB for testing. If the payment interface appears successfully after submission, it means your site\'s Alipay function can be used normally',
	'ec_alipay_check_virtualgoodssubject' => 'Test Virtual Goods',
	'ec_alipay_check_goodssubject' => 'Test Physical Goods',
	'ec_alipay_checklink_credit' => 'Credit Recharge Order Test',
	'ec_alipay_checklink_virtualgoods' => 'Virtual Goods Order Test',
	'ec_alipay_checklink_goods' => 'Physical Goods Order Test',
	'ec_contract' => 'Alipay Contract User Settings',
	'ec_alipay_contract' => 'Use Alipay Contract Interface',
	'ec_alipay_contract_comment' => 'If your Alipay account is a contracted user, you can select "Yes" to let the forum use your own merchant service platform. If you have not signed yet, <a href="http://act.life.alipay.com/systembiz/discuz/" target="_blank">please click here to sign</a>',
	'ec_alipay_securitycode' => 'Transaction Security Verification Code (key)',
	'ec_alipay_securitycode_comment' => 'Alipay contracted users can fill in the transaction security verification code assigned to you by Alipay here. This verification code can be viewed in the official Alipay merchant service function',
	'ec_alipay_partner' => 'Partner Identity (PID)',
	'ec_alipay_partner_comment' => 'Alipay contracted users please fill in the partner identity assigned to you by Alipay here. The handling fee for contracted users is subject to the agreement you signed with Alipay official.<br/>If you have not signed up yet, <a href="http://act.life.alipay.com/systembiz/discuz/" target="_blank">please click here to sign up</a>; if you have signed up, <a href="https://b.alipay.com/order/pidKey.htm?pid=2088501719138773&product=fastpay" id="aliapitype" target="_blank">please click here to get PID and Key</a>; if there is a contract template conflict during signing, please consult 0571-88158090',
	'ec_alipay_creditdirectpay' => 'Use Instant Payment Interface Only',
	'ec_alipay_creditdirectpay_comment' => 'If your contract agreement includes a pure instant payment interface (not a standard dual interface), you can select this option so that credit recharge can only use instant payment method',
	'ec_alipay_sign_mode' => 'Signature Mode',
	'ec_alipay_sign_mode_01' => 'Normal Public Key Mode Signature',
	'ec_alipay_sign_mode_02' => 'Public Key Certificate Mode Signature',
	'ec_alipay_sign_mode_comment' => 'Alipay Open Platform: <a href="https://open.alipay.com/" target="_blank">View</a>; For enterprise developers involving <a href="https://opendocs.alipay.com/open/291/hfaalq" target="_blank">fund expenditure APIs</a>, must use <b>public key certificate mode signing</b>; For individual developers not involving fund APIs, it is recommended to use <b>normal public key mode signing</b> for signing; <b>API Signing</b>: <a href="https://opendocs.alipay.com/mini/introduce/01p6u8" target="_blank">Configure API signing method</a>',
	'ec_alipay_appid' => '(Required) App ID',
	'ec_alipay_appid_comment' => 'App ID assigned by Alipay to developers, <a href="https://open.alipay.com/platform/developerIndex.htm" target="_blank">View my app list</a>',
	'ec_alipay_app_private_key' => '(Required) RSA2(SHA256) Developer Private Key',
	'ec_alipay_app_private_key_comment' => 'For details on obtaining normal public key mode, please see <a href="https://opendocs.alipay.com/open/291/105971#%E6%99%AE%E9%80%9A%E5%85%AC%E9%92%A5%E6%96%B9%E5%BC%8F" target="_blank">Get Normal Public Key</a>',
	'ec_alipay_app_private_key_b_comment' => 'For details on obtaining public key certificate mode, please see <a href="https://opendocs.alipay.com/open/291/105971#%E5%85%AC%E9%92%A5%E8%AF%81%E4%B9%A6%E6%96%B9%E5%BC%8F" target="_blank">Get Public Key Certificate</a>',
	'ec_alipay_public_key' => '(Required) RSA2(SHA256) Alipay Public Key',
	'ec_alipay_public_key_comment' => 'For details on obtaining normal public key mode, please see <a href="https://opendocs.alipay.com/open/291/105971#%E6%99%AE%E9%80%9A%E5%85%AC%E9%92%A5%E6%96%B9%E5%BC%8F" target="_blank">Get Normal Public Key</a>',
	'ec_alipay_app_cert' => '(Required) RSA2(SHA256) App Public Key Certificate',
	'ec_alipay_app_cert_comment' => 'For details on obtaining public key certificate mode, please see <a href="https://opendocs.alipay.com/open/291/105971#%E5%85%AC%E9%92%A5%E8%AF%81%E4%B9%A6%E6%96%B9%E5%BC%8F" target="_blank">Get Public Key Certificate</a>; appCertPublicKey_*.crt, open this file with Notepad, select all and copy the content here',
	'ec_alipay_alipay_cert' => '(Required) RSA2(SHA256) Alipay Public Key Certificate',
	'ec_alipay_alipay_cert_comment' => 'For details on obtaining public key certificate mode, please see <a href="https://opendocs.alipay.com/open/291/105971#%E5%85%AC%E9%92%A5%E8%AF%81%E4%B9%A6%E6%96%B9%E5%BC%8F" target="_blank">Get Public Key Certificate</a>; alipayCertPublicKey_RSA2.crt, open this file with Notepad, select all and copy the content here',
	'ec_alipay_alipay_root_cert' => '(Required) RSA2(SHA256) Alipay Root Certificate',
	'ec_alipay_alipay_root_cert_comment' => 'For details on obtaining public key certificate mode, please see <a href="https://opendocs.alipay.com/open/291/105971#%E5%85%AC%E9%92%A5%E8%AF%81%E4%B9%A6%E6%96%B9%E5%BC%8F" target="_blank">Get Public Key Certificate</a>; alipayRootCert.crt, open this file with Notepad, select all and copy the content here',
	'ec_alipay_check' => 'Payment Test',

	'ec_wechat' => 'WeChat Pay Settings',
	'ec_wechat_tips' => '<li>WeChat Pay (https://pay.weixin.qq.com) is China\'s leading third-party payment platform under Tencent Group. It has been committed to providing users and enterprises with secure, convenient, and professional online payment services. With the core concept of "WeChat Pay, More Than Payment", it creates various convenient services and application scenarios for individual users, and provides professional collection capabilities, operational capabilities, fund settlement solutions, and security guarantees for various enterprises and small and micro merchants. Enterprises, goods, stores, and users have been connected through WeChat, making smart life a reality.</li><li><b>Due to cash transactions involved, to avoid financial losses caused by improper operation, please carefully read the e-commerce section in the User Manual before starting to use the WeChat Pay credit transaction function (excluding the Alipay button function), and make related settings after confirming full understanding and acceptance of the relevant processes and usage methods.</b></li><li>Your use of WeChat Pay services is based on complete voluntariness. Except for financial losses caused by Discuz! subjective malicious factors, Tencent Cloud shall not be liable for any losses caused by using this function.</li><li>WeChat Pay customer service phone number is 95017.</li>',
	'ec_wechat_on' => 'Whether to Enable WeChat Pay',
	'ec_wechat_version' => 'API Version',
	'ec_wechat_version_comment' => 'APIV3 requires PHP version >= 7.2',
	'ec_wechat_version_2' => 'API',
	'ec_wechat_version_3' => 'APIV3',
	'ec_wechat_appid' => '(Required) Official Account APPID',
	'ec_wechat_appid_comment' => 'WeChat Official Account must have WeChat Merchant Platform enabled',
	'ec_wechat_appsecret' => '(Required) Official Account APPSECRET',
	'ec_wechat_mch_id' => '(Required) Merchant ID',
	'ec_wechat_mch_id_comment' => 'Merchant ID assigned by WeChat Pay',
	'ec_wechat_v1_key' => '(Required) API Key',
	'ec_wechat_v1_key_comment' => 'WeChat Merchant Platform --> Account Settings --> API Security --> Key Settings - API Key',
	'ec_wechat_v1_cert' => '(Optional) Payment Certificate Path',
	'ec_wechat_v1_cert_comment' => 'Location of cert.p12 certificate; it is recommended to modify the file name to avoid direct access; used for refunds, can be left blank if no refund business. Must be in the website directory, e.g.: source/data/{randomstr}.p12',
	'ec_wechat_v3_private_key' => '(Required) API Certificate Private Key',
	'ec_wechat_v3_private_key_comment' => 'When merchants apply for/replace merchant API certificates (WeChat Merchant Platform --> Account Settings --> API Security --> API Certificate), an API certificate private key will be generated and saved in the file apiclient_key.pem in the local certificate folder.',
	'ec_wechat_v3_serial_no' => '(Required) API Certificate Serial Number',
	'ec_wechat_v3_serial_no_comment' => 'In <a href="https://pay.weixin.qq.com/" target="_blank">WeChat Pay Merchant Platform</a> - Account Center - <a href="https://pay.weixin.qq.com/index.php/core/cert/api_cert" target="_blank">API Security</a> - API Certificate - View Certificate - Certificate Serial Number',
	'ec_wechat_v3_key' => '(Required) APIV3 Key',
	'ec_wechat_v3_key_comment' => 'WeChat Merchant Platform --> Account Settings --> API Security --> Key Settings - APIv3 Key',
