	'ec_qpay' => 'QQ Wallet Settings',
	'ec_qpay_tips' => '<li>QQ Wallet is a third-party payment platform under Tenpay of Tencent Group. It has been committed to providing users and enterprises with secure, convenient, and professional online payment services.</li><li><b>Due to cash transactions involved, to avoid financial losses caused by improper operation, please carefully read the e-commerce section in the User Manual before starting to use the QQ Wallet credit transaction function (excluding the Alipay button function), and make related settings after confirming full understanding and acceptance of the relevant processes and usage methods.</b></li><li>You can set to allow users to recharge their trade credit accounts through online cash payment, for purchasing post content, purchasing user group permissions, credit transfer, or user group upgrade functions. Please be sure to correctly set your collection information, otherwise it will cause credits not to be credited in real-time after users pay, resulting in a large number of orders requiring manual processing.</li><li>Your use of QQ Wallet services is based on complete voluntariness. Except for financial losses caused by Discuz! subjective malicious factors, Tencent Cloud shall not be liable for any losses caused by using this function.</li><li>Tenpay service hotline: 0755-83762288-2 (24-hour service hotline), QQ Wallet customer service email is qpay@tencent.com.</li>',
	'ec_qpay_on' => 'Whether to Enable QQ Wallet Payment',
	'ec_qpay_jsapi' => 'Whether to Enable QQ Wallet JSAPI Payment',
	'ec_qpay_jsapi_comment' => 'Need to add a payment authorization domain approved by Tencent. If you do not have this permission or cannot pay after enabling, please turn it off',
	'ec_qpay_appid' => '(Optional) App ID',
	'ec_qpay_appid_comment' => 'App ID approved by Tencent Open Platform or QQ Connect Platform',
	'ec_qpay_mch_id' => '(Required) Merchant ID',
	'ec_qpay_mch_id_comment' => 'Merchant ID assigned by QQ Wallet',
	'ec_qpay_op_user_id' => '(Optional) Operator ID',
	'ec_qpay_op_user_id_comment' => 'Operator account used for refunds, defaults to merchant ID',
	'ec_qpay_op_user_passwd' => '(Optional) Operator Password',
	'ec_qpay_op_user_passwd_comment' => 'Operator password used for refunds, saved with md5 encoding in the system',
	'ec_qpay_v1_key' => '(Required) API Key',
	'ec_qpay_v1_key_comment' => 'QQ Wallet Merchant Platform --> Account Management --> API Security',
	'ec_qpay_v1_cert' => '(Optional) Payment Certificate Path',
	'ec_qpay_v1_cert_comment' => 'Location of cert.p12 certificate; it is recommended to modify the file name to avoid direct access; used for refunds, can be left blank if no refund business. Must be in the website directory, e.g.: source/data/{randomstr}.p12',
	'ec_qpay_check' => 'Payment Test',
	'ec_qpay_checklink_credit' => 'Credit Recharge Order Test',

	'ec_orders' => 'Credit Recharge Orders',
	'ec_orders_tips' => '<li>Before starting to use the Alipay credit transaction order management function (excluding the Alipay button function), please carefully read the e-commerce section in the User Manual, and perform related operations after confirming full understanding and acceptance of the relevant processes and usage methods.</li><li>If your users report that their credit accounts cannot be automatically recharged after online payment, it may be due to incorrect notification interface settings of your Alipay account, or your website cannot be normally accessed by the Alipay notification system. You can log in to the Alipay transaction management interface and manually confirm relevant orders by comparing transaction details.</li><li>Order information is retained for 60 days, so you can only query and manage order information within 60 days. Information exceeding 60 days will be automatically deleted.</li>',
	'ec_orders_search' => 'Credit Recharge Order Search',
	'ec_inviteorders_search' => 'Invitation Code Order Search',
	'ec_inviteorders_status' => 'Order Status',
	'ec_orders_search_email' => 'Buyer Email',
	'ec_orders_search_status' => 'Order Status',
	'ec_orders_search_status_all' => 'All Statuses',
