	'tools_updatecache' => 'Update Cache',
	'tools_updatecache_tips' => '<li>When the site has undergone data recovery, upgrade, or abnormal operation, you can use this function to regenerate the cache. When updating the cache, it may increase server load, please try to avoid peak member access times</li>
				<li>Data Cache: Update all data caches of the site</li>
				<li>Template Cache: Update cache files such as forum templates and styles, used when you have modified templates or styles but they have not taken effect immediately</li>
				<li>Object Storage Cache: After enabling object storage, update static files such as CSS, JS to object storage</li>
				<li>DIY Module Category Cache: Update DIY module categories, used when you have installed or modified DIY module categories but they have not taken effect immediately</li>
				<li>CSS Cache: Update CSS files such as forum templates and styles, used when you have modified template or style CSS but they have not taken effect immediately</li>
				',

