	'db' => 'Database',
	'db_export' => 'Data Backup',
	'db_method' => 'Method',
	'db_shell' => 'Shell',
	'db_multivol' => 'Multi-volume',
	'db_zip' => 'ZIP',
	'db_volume' => 'Volume Count',
	'db_delete_tips' => '<br /><br /><a href="'.ADMINSCRIPT.'?action=db&operation=import&deletesubmit=1&delete[]={filename}&formhash={FORMHASH}" onclick="return confirm(\'Are you sure you want to delete the backup data on the server?\');"><font color="#fe7e01"><strong>Delete backup data on server</strong></font></a>',
	'db_export_tips_nouc' => '<li><font color="blue"><b>Your current data backup does not include UCenter, which will affect your member data. Please click <a href="{uc_backup_url}">here</a> to backup UCenter data separately</b></font></li><li>The data backup function backs up all Discuz! data according to your selection. The exported data files can be imported using the "Data Recovery" function or phpMyAdmin.</li>',
	'db_export_tips_uc' => '<li>The data backup function backs up all Discuz! and UCenter data according to your selection. The exported data files can be imported using the "Data Recovery" function or phpMyAdmin.</li>',
	'db_export_tips' => '<li><font color="blue"><b>For security reasons, we strongly recommend that you delete the database backup file after downloading or set the file to be inaccessible via URL.</b></font></li><li>All backups do not include template files and attachment files. To back up templates and attachments, simply download the template/ and data/attachment/ directories via FTP, etc. Discuz! does not provide separate backups.</li><li>The settings in the data backup options are only for special purposes of advanced users. Before you have a comprehensive understanding of the database, please use the default parameters for backup, otherwise it will cause serious problems such as backup data errors.</li><li>The hexadecimal method can ensure the integrity of backup data, but the backup file will take up more space.</li><li>Compressing backup files can make your backup files take up less space.</li><li>To restore backup data, please use the built-in toolbox of the Discuz! installer (rename install/index.php and then access it)</li>',
	'db_export_type' => 'Data Backup Type',
