	'db_import' => 'Data Recovery',
	'db_import_confirm' => 'Importing data inconsistent with the current Discuz! version is very likely to cause unsolvable problems. Are you sure you want to continue?',
	'db_import_confirm_sql' => 'Are you sure you want to import this backup?',
	'db_import_confirm_zip' => 'Are you sure you want to decompress this backup?',
	'db_import_tips' => '<li>This function will completely overwrite the original data while restoring backup data. Please make sure the site is closed before restoration, and the site can be reopened after restoration is fully completed.</li><li><font color="blue"><b>For security reasons, we strongly recommend that you delete the database backup file after restoration or set the file to be inaccessible via URL.</b></font></li><li>Before restoring data, please find the restore.php file in the utility folder under the Discuz! installation file directory, then upload the restore.php file to the data directory of the program folder. <b>For the security of your site, please be sure to delete the restore.php file promptly after successful data restoration.</b></li><li>You can view detailed information about the site\'s backup files at the data backup record, delete expired backups, and import needed backups.</li>',
	'do_import_option' => '<ul><li>You can import backup recovery data at the data backup record on this page, or you can restore data by executing <a href="{restore_url}" target="_blank">{restore_url}</a> in the browser',
	'db_import_from_server' => 'From Server (fill in file name or URL)',
