	'db_runquery' => 'Database Upgrade',
	'db_runquery_tips' => '<li>You can add common SQL operations for function expansion by modifying /source/admincp/admincp_quickquery.php.</li><li>For security reasons, Discuz! Admin CP prohibits direct execution of SQL statements by default, and can only use content from common SQL. <br />If you want to freely write SQL upgrade statements yourself, you need to modify the $_config[\'admincp\'][\'runquery\'] setting in config/config_global.php to 1.</li>',
