	'adv_type_version' => 'Module Version',
	'adv_type_headerbanner' => 'Header Banner Ad',
	'adv_type_headerbanner_tips' => '<li>Display method: Header banner ads are displayed at the top right of the forum page, usually in the form of 468x60 images or Flash. When there are multiple header banner ads on the current page, the system will randomly select one to display.</li><li>Value analysis: Because they can display ad content in the most prominent position as soon as the page opens, they have become one of the highest-priced ad types on web pages, most suitable for commercial promotion or brand promotion.</li>',
	'adv_type_footerbanner' => 'Footer Banner Ad',
	'adv_type_footerbanner_tips' => '<li>Display method: Footer banner ads are displayed in the lower middle of the forum page, usually in the form of 468x60 or other size images or Flash. When there are multiple footer banner ads on the current page, the system will randomly select one to display.</li><li>Value analysis: Compared with the page header and middle, the display probability of the page footer is relatively low, usually not causing visitor dislike, while basically covering all audiences interested in the ad content, thus suitable for neutral and gentle promotion.</li>',
	'adv_type_text' => 'In-page Text Ad',
	'adv_type_text_tips' => '<li>Display method: In-page text ads are displayed in table form in the upper middle of three pages: homepage, thread list, and post content. Usually in text form, but can also use small images and Flash. When there are multiple text ads on the current page, the system will display all of them in table form according to the set display order, and can dynamically arrange the number of table columns within the range of 3 to 5 to automatically achieve the best ad arrangement effect.</li><li>Value analysis: Because such ads are usually displayed in text form, but their position higher on the page makes them one of the must-read content for visitors. The characteristic that a single page can present up to a dozen text ads also determines that it is a popular but cost-effective promotion method, and can also be used for the forum\'s own promotion and announcements.</li>',
	'adv_type_thread' => 'In-post Ad',
	'adv_type_thread_tips' => '<li>Display method: In-post ads are displayed above, below, or to the right of post content. Above and below post content usually use text form, and to the right of post content usually use image form. When there are multiple in-post ads on the current page, the system will randomly select the same number of entries as posts per page for display. You can modify the number of ads displayed per post in other settings in global settings.</li><li>Value analysis: Because posts are the most core component of the forum, in-post ads embedded inside post content can be naturally accepted when users browse post content. Combined with the random display feature, they are suitable for effective promotion of specific content, and can also be used for the forum\'s own promotion and announcements. It is recommended to set multiple in-post ads to achieve differentiation of ad content, thereby attracting more visitor attention.</li>',
	'adv_type_interthread' => 'Inter-post Banner Ad',
	'adv_type_interthread_tips' => '<li>Display method: Inter-post banner ads are displayed between the first post and the first reply. Can use 468x60 or other size images and Flash. When there are multiple inter-post banner ads on the current page, the system will randomly select one to display.</li><li>Value analysis: Because they can separate the thread from replies, the ad size is large and does not affect post content, so it will not cause dislike from post authors and visitors. Suitable for commercial promotion or brand promotion within posts.</li>',
	'adv_type_float' => 'Floating Ad',
	'adv_type_float_tips' => '<li>Display method: Floating ads are displayed in the bottom left corner of the page. When the page scrolls, the ad will move by itself to maintain its original position, usually in the form of small images or Flash. When there are multiple floating ads on the current page, the system will randomly select one to display.</li><li>Value analysis: Floating ads are an effective means of strong commercial promotion. Their floating nature on the page makes them easier to notice than fixed images and text. Precisely because of this, this forced attention may also cause dislike from visitors who are not interested in the ad content. Please do not display overly large images or Flash as floating ads, so as not to affect page reading.</li>',
	'adv_type_couplebanner' => 'Couplet Ad',
	'adv_type_couplebanner_tips' => '<li>Display method: Couplet ads are displayed on both sides of the top of the page in the form of rectangular images, resembling a couplet. Usually using small-width, large-height rectangular images or Flash. Couplet ads are generally only used when the main table width is specified in pixels. If the main table width is specified as a percentage exceeding 90%, it may affect normal browsing of visitors. When the visitor\'s browser width is less than 800 pixels, such ads are automatically hidden. When there are multiple couplet ads on the current page, the system will randomly select one to display.</li><li>Value analysis: Because couplet ads are only displayed on both sides of high-resolution (1024x768 or higher) screens, only occupying blank areas of the page, they do not cause visitor dislike and can well highlight promoted content. However, due to special requirements for resolution and main table width, the audience ratio of the ad cannot reach 100%.</li>',
	'adv_type_intercat' => 'Inter-category Ad',
	'adv_type_intercat_tips' => '<li>Display method: Inter-category ads are displayed between two adjacent forum categories on the forum homepage. Can use 468x60 or other size images and Flash. When there are multiple inter-category ads on the current page, the system will randomly select the same number of entries as forum categories for display.</li><li>Value analysis: Because they appear in a prominent position on the forum homepage, the ad display effect is good, but too many or too large homepage ads may cause visitor dislike. </li>',
