	'adv_list_tip' => '<li>You can use "Custom Ad Position" to add ad positions anywhere on the page.<li>System ad positions are located in the source/class/adv/ directory, plugin ad positions are located in source/plugin/plugin_directory/adv/ directory.</li><li>Plugin developers must carefully read the content in the <a href="https://open.dismall.com/?!devdoc" target="_blank">Discuz! Technical Documentation</a> before designing new ad positions.</li><li>Adding &lt;!--{ad/addon_*}--&gt; in template files can dynamically add custom ad positions.</li>',
