	'blockstyle_add_tips' => '<li>You can use the [loop]...[/loop] tag to loop display data in the module; if you want to loop in multiple places in the template, you can use [loop1]...[/loop1] to extend (can only extend 1-9)</li><li>You can use [order=N]...[/order] tag to replace the display of the Nth position data in the default loop. You can use [order1=N]...[/order1] to extend (corresponding to [loop1])</li><li>You can use [index=N]...[/index] to specify the display method of the Nth data item. Data specified by this syntax will no longer appear in the loop. You can extend it through [index1]...[/index1] (can only extend 1-9) to achieve multiple displays of the same data item</li><li>You can use image tags that can generate thumbnails / links that can specify the open method, and specify thumbnail size / link open method when generating the module</li><li>Some modules (such as static modules) have content generated by data sources and do not need corresponding templates</li><li>Field items (e.g., {title}) only take effect within [loop], [order], [index] tags</li>',
