	'postsplit_manage_tips' => '<li>Be sure to close the site before post table splitting. To prevent problems during table splitting, <strong>database backup must be done</strong> before performing this operation</li><li>After post data transfer is complete, table optimization will be performed on the source post table. Table optimization takes a relatively long time, <strong>during which the server must never be restarted or MySQL service stopped</strong></li><li>forum_post (primary table) must retain 300M of data</li><li>Post table splitting function can split posts into different data tables, suitable for sites with many posts and affected operational efficiency</li>',
