	'threadsplit_manage_tips' => '<li>The thread table splitting function can split the forum_thread table (containing thread titles, creation time, etc., but not thread and reply content) into multiple data tables.</li><li>After creating a new thread archive table, you can use the thread move function to move specific threads to the archive table.</li><li>Threads moved to the archive table will have an archive area (customizable name) created under the forum where the thread is located. Threads in the archive table can be browsed through the archive area.</li><li>Threads in the archive table are for browsing only, cannot be replied to, rated, or managed, but can be deleted and moved to non-archive areas.</li>',
