	'rewrite_message' => '<h1>Apache Web Server (Dedicated Hosting Users)</h1>
<pre class="colorbox">
&lt;IfModule mod_rewrite.c&gt;
	RewriteEngine On
{apache1}&lt;/IfModule&gt;
</pre>

<h1>Apache Web Server (Virtual Hosting Users)</h1>
<pre class="colorbox">
# Turn on RewriteEngine mode
RewriteEngine On

# For example www.discuz.vip/bbs/, corresponding to RewriteBase /bbs/, if the program is placed in the root directory, use RewriteBase /
RewriteBase {siteroot}

# Do not modify Rewrite system rules
{apache2}
</pre>

<h1>Nginx Web Server</h1>
<pre class="colorbox">
{nginx}
</pre>

<h1>IIS Web Server (Dedicated Hosting Users)</h1>
<pre class="colorbox">
[ISAPI_Rewrite]

# 3600 = 1 hour
CacheClockRate 3600

RepeatLimit 32

# Protect httpd.ini and httpd.parse.errors files
# from accessing through HTTP
{iis}
</pre>

<h1>IIS7 Web Server (Dedicated Hosting Users)</h1>
<pre class="colorbox">
&lt;rewrite&gt;
	&lt;rules&gt;
{iis7}	&lt;/rules&gt;
&lt;/rewrite&gt;
</pre>

<h1>Lighttpd Web Server</h1>
<pre class="colorbox">
url.rewrite-once = (
{lighttpd})
</pre>

<h1>Caddy Web Server</h1>
<pre class="colorbox">
{caddy}
</pre>',

