					<pre class="colorbox" style="width: 500px">$sign = base64_encode(hash(\'sha256\', $nonce.$t.$secret));</pre></p>
					<p class="mtm">Javascript：
					<pre class="colorbox" style="width: 500px">
function getSign(nonce, t, secret) {
    let sha256 = CryptoJS.SHA256(nonce + t + secret).toString();
    let base64_sign = CryptoJS.enc.Base64.stringify(CryptoJS.enc.Utf8.parse(sha256));
    return base64_sign;
}					
</pre>
				</p>',
