if(file_exists($adminextendfile = DISCUZ_DATA.'./sysdata/cache_adminextend.php')) {
	@include $adminextendfile;
	foreach($adminextend as $extend) {
		$extend_lang = [];
		@include DISCUZ_ROOT.'./source/i18n/'.currentlang().'/lang_admincp_'.$extend;
		$lang = array_merge($lang, $extend_lang);
	}
}

